-- CA Guru AI: Books + MCQ seed (run in Supabase SQL editor)
-- Safe to re-run. Creates books, mcq_questions, storage bucket + seeds.
begin;

-- Books table
create table if not exists public.books (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  author text,
  level text not null check (level in ('Foundation', 'Intermediate', 'Final')),
  subject_id uuid references public.subjects(id) on delete set null,
  description text,
  file_path text,
  external_url text,
  file_size int,
  page_count int,
  cover_path text,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.books enable row level security;

create policy "Authenticated can read books" on public.books
  for select to authenticated using (true);

do $$
begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='books' and policyname='Content admins can insert books') then
    create policy "Content admins can insert books" on public.books for insert to authenticated
      with check (exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='books' and policyname='Content admins can update books') then
    create policy "Content admins can update books" on public.books for update to authenticated
      using (exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='books' and policyname='Content admins can delete books') then
    create policy "Content admins can delete books" on public.books for delete to authenticated
      using (exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
end
$$;

-- Storage bucket + policies
insert into storage.buckets (id, name, public, file_size_limit)
values ('ca-materials', 'ca-materials', true, 104857600)
on conflict (id) do update set public = true, file_size_limit = 104857600;

do $$
begin
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Authenticated read ca-materials') then
    create policy "Authenticated read ca-materials" on storage.objects
      for select to authenticated using (bucket_id = 'ca-materials');
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Content admins upload ca-materials') then
    create policy "Content admins upload ca-materials" on storage.objects for insert to authenticated
      with check (bucket_id = 'ca-materials' and exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Content admins delete ca-materials') then
    create policy "Content admins delete ca-materials" on storage.objects for delete to authenticated
      using (bucket_id = 'ca-materials' and exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
end
$$;

-- Darshan Khare book row
insert into public.books (title, author, level, subject_id, external_url, description)
select 'CA Inter Law MCQs by Darshan Khare', 'Darshan Khare', 'Intermediate',
  (select id from public.subjects where code = 'P2' and level = 'Intermediate' limit 1),
  'https://cdn.shopify.com/s/files/1/0023/3200/0311/files/CA_Inter_Law_MCQs_by_Darshan_Khare.pdf?15995338007595527142',
  'Chapter-wise Law MCQs for CA Intermediate preparation'
where not exists (select 1 from public.books where title = 'CA Inter Law MCQs by Darshan Khare');

-- MCQ questions table
create table if not exists public.mcq_questions (
  id uuid primary key default gen_random_uuid(),
  book_id uuid references public.books(id) on delete cascade,
  chapter_no int not null default 1,
  chapter_title text,
  question_no int not null,
  question text not null,
  options jsonb not null default '[]'::jsonb,
  correct_index int,
  hint text,
  created_at timestamptz not null default now(),
  unique (book_id, chapter_no, question_no)
);
alter table public.mcq_questions enable row level security;

create policy "Authenticated can read mcq_questions" on public.mcq_questions
  for select to authenticated using (true);

do $$
begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='mcq_questions' and policyname='Content admins can insert mcq_questions') then
    create policy "Content admins can insert mcq_questions" on public.mcq_questions for insert to authenticated
      with check (exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='mcq_questions' and policyname='Content admins can update mcq_questions') then
    create policy "Content admins can update mcq_questions" on public.mcq_questions for update to authenticated
      using (exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='mcq_questions' and policyname='Content admins can delete mcq_questions') then
    create policy "Content admins can delete mcq_questions" on public.mcq_questions for delete to authenticated
      using (exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('admin','teacher')));
  end if;
end
$$;


-- ==================== CHAPTER 1 ====================

-- Chapter 1: Preliminary and Basics of Company Law
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 1, 'Preliminary and Basics of Company Law', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'Property of the Company belongs to ------------.', '["Company","Shareholders","Members","Promoters"]'::jsonb, 0, 'As per Section 9 of Companies Act, 2013, (Property of the Company is not the property of the shareholders, it is property of the Company because Company is separate legal entity from shareholders'),
(2, 'Mr. X, shareholder of A Ltd. used the property of the Company for his personal use, he did not enter into any contract with the Company for such sale, whether the shareholder of the Company can use the property of the Company for their own personal purpose?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 9 of Companies Act, 2013, Property of the Company is not the property of the shareholders, it is property of the Company because Company is separate legal entity from shareholders'),
(3, 'The term Company is defined under which section of the Companies Act, 2013?', '["Section 2 (20)","Section 2 (10)","Section 2 (4)","Section 2 (3)"]'::jsonb, 0, NULL),
(4, 'Minimum number of partners required under Partnership Firm?', '["2","7","3","None of the above"]'::jsonb, 0, NULL),
(5, 'Partnership firm is separate legal entity from its partners. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 1, 'Partnership firm is not a separate legal entity from its partners'),
(6, 'How to dissolve Partnership Firm under Partnership Act, 1932?', '["By agreement of partners","By mutual consent of partners and by court order","By insolvency and by certain contingencies","All of the above"]'::jsonb, 3, NULL),
(7, 'Registration of Partnership Firm is optional. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'As per Partnership Act, registration of Partnership Firm is optional'),
(9, 'Company registered under Companies Act, 2013 is separate legal entity from its members?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 9 of Companies Act, 2013, Company have its own identity, its own legal entity like other human'),
(10, 'How to dissolve Company under Companies Act, 2013?', '["Voluntary","Order of National Company Law Tribunal","Either a or b","None of the above"]'::jsonb, 2, NULL),
(11, 'Minimum number of members in case of Public Company?', '["1","2","5","7"]'::jsonb, 3, 'Public Company is incorporated by minimum 7 members'),
(12, 'Minimum number of members in case of Private Company?', '["1","7","2","4"]'::jsonb, 2, 'Private Company is incorporated by minimum 2 members'),
(15, 'Which company shares can be freely transferable?', '["Private Company","Public Company","Both a and b","None of the above"]'::jsonb, 1, 'members of the Company have right to transfer their share'),
(16, 'Minimum number of directors in case of a Public Company is-------.', '["1","2","3","4"]'::jsonb, 2, 'As per section 149 (1) of the companies Act, 2013'),
(17, 'Minimum number of directors in case of a Private company is-------.', '["1","2","3","4"]'::jsonb, 1, 'As per section 149 (1) of the companies Act, 2013'),
(19, 'Maximum paid up share capital in case of Public Company------------.', '["Rs. 50 Lakhs","Unlimited","Rs. 1 Crore","None of the above"]'::jsonb, 1, 'there is no max limit on capital of the company'),
(20, 'Maximum paid up share capital in case of One Person Company------------.', '["Rs. 50 Lakhs","Rs. 1 Crore","Unlimited","None of the above"]'::jsonb, 0, 'there is max limit on capital of the company'),
(21, 'Maximum paid up share capital in case Small Company------------.', '["Rs. 50 Lakhs to Rs. 5 Cr.","As per Central Govt.","Either a or b","None of the above"]'::jsonb, 2, NULL),
(22, 'M/s ABC, is a Private Limited Company is desirous for inviting the public for subscription of its issue. Can the Company do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'right of members to transfer the shares can be restricted by article'),
(23, 'Which Company is free to invite public for subscription?', '["Public Company","Private Company","One Person Company","Small Company"]'::jsonb, 0, NULL),
(24, 'Maximum annual turnover in case of One Person Company------------.', '["Rs. 2 Crore","1 Crore","Rs. 10 Crore","5 Crore"]'::jsonb, 0, 'there is max limit on turnover of the company'),
(25, 'The Private Company which is the subsidiary of the Public Company will also be considered as the Public Company under Section 2 (71) of the Companies Act, 2013. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, NULL),
(27, 'Minimum number of directors in case of a One Person Company is-------.', '["2","4","3","1"]'::jsonb, 3, 's per section 149 (1) of the companies Act, 2013'),
(28, 'Minimum number of members in case of One Person Company?', '["1","2","7","None of the above"]'::jsonb, 0, 'One member is also sufficient for incorporation of One Person Company'),
(29, 'A Company is a legal entity but not a citizen. Is this statement true?', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'the citizenship in India is available for Individual only. As the company is not an individual'),
(30, 'Punishment for improper use of word Ã¢â‚¬Å“LimitedÃ¢â‚¬Â or Ã¢â‚¬Å“Private LimitedÃ¢â‚¬Â.', '["Rs. 500 per day during use of such name","Rs. 2000 per day during use of such name","Rs. 500 to Rs.2000 per day during use of such name","None of the above"]'::jsonb, 2, NULL),
(31, 'Mr. A wants to incorporate One Person Company individually. Can he do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'One member is also sufficient for incorporation of One Person Company'),
(32, 'Mr. Superman is a truck driver formed company for testing trucks. The name of the company is Thhok Diya Ltd. Mr. Superman was also an employee having a contract of compensation with Thhok Diya Ltd. in case of damage to him or his life. At one day Mr. Superman drove a truck and went into accident with bicycle and lost his life. Now his widow want to claim compensation from Thhok Diya Ltd. Whether wife of the Superman can receive the compensation from the company?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'There was valid contract between the company and Mr. Superman'),
(33, 'MN Limited Company, desirous for inviting the public for subscription of its issue. Can the Company do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Public Company is free to invite public for subscription'),
(34, 'As per Section 2(87) of the Companies Act, 2013, Subsidiary Company in relation to any other company means a company in which the holding company-----------.', '["Controls the composition of the board of directors","Exercises or controls more than one Ã¢â‚¬â€œ half of the total voting power either at its own or together with one or more of its subsidiary companies","Either option a or b","None of the above"]'::jsonb, 2, NULL),
(35, 'H Ltd. holds more than 52% voting rights of S Ltd., Whether S Ltd. is a subsidiary of H Ltd.?', '["Yes","No","Partly Yes","CanÃ¢â‚¬â„¢t say"]'::jsonb, 0, 'Exercises or controls more than one Ã¢â‚¬â€œ half of the total voting power either at its own or together with one or more of its subsidiary companies'),
(38, 'As per Section 2(45) of the Companies Act, 2013, Government Company means any company in which not less than 51% of the paid up share capital is held by-----------', '["By the Central Government","By any state Government or Governments","Partly by the Central Government and partly by one or more state Governments","All of the above"]'::jsonb, 3, NULL),
(40, 'H is public limited company in which 52% of paid up share capital held by Central Government, whether H limited is government company as per Section 2(45) of the Companies Act, 2013.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'any company in which not less than 51% of the paid up share capital is held by central Government Company is called Government company'),
(41, 'MN is public limited company in which 52% of paid up share capital held by State Government, whether MN limited is government company as per Section 2(45) of the Companies Act, 2013.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'any company in which not less than 51% of the paid up share capital is held by any state Government or Gov ernments'),
(42, 'MNN is public limited company in which 30% of paid up share capital held by Central Government and 30% of the paid share capital held by State Government, whether MNN limited is government company as per Section 2(45) of the Companies Act, 2013.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'any company in which not less than 51% of the paid up share capital is Partly by the Central Government and partly by one or more state Governments'),
(43, 'Whether Foreign LLP are also considered under Foreign Company under the Companies Act, 2013', '["Yes","No","Partly yes","Partly No"]'::jsonb, 0, 'because it is body corporate'),
(44, 'Whether shares held in fiduciary capacity are to be counted for making company a subsidiary?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, NULL),
(45, 'Whether shares held by virtue of provisions of any debentures are to be counted for making company a subsidiary?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, NULL),
(46, 'What will be the status of the Private Company which is subsidiary of the foreign Company?', '["Private Company","Public Company","Option a or b","CanÃ¢â‚¬â„¢t say"]'::jsonb, 0, NULL),
(48, 'According to Section 2(42) of the Companies Act, 2013, Foreign Company means any company or body corporate incorporated outside India which-----------', '["Company or body corporate incorporated outside India and majority of shareholders are out of India","Conduct any business activity in India in any manner","Has a place of business in India whether by itself or through agent, physically or through electronic mode","All of the above"]'::jsonb, 3, NULL),
(49, 'If the foreign Company have place of business in India but does not conduct the business from such place, whether that Company is considered as Foreign Company according to Section 2(42) of the Companies Act, 2013?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'One of the basic condition is to conduct the business from India'),
(50, 'The subsidiary Company hold shares in the holding company before the holding company becomes the holding company of such subsidiary. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'Section 19 of the Companies Act prohibits the subsidiary company from holding the shares in the Holding Company except in above situation'),
(51, 'The company can take away ownership from management?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 9 of Companies Act , 2013, the Company is combination of separate 3 pillar i.e. Investor, Management and Auditor. Investor invest the money which is used by management to run business and auditor checked whether money is being properly used or not'),
(52, 'The investor need not enter in to day to day transaction of the Company or management of the Company. True or false.', '["True","False","Partly True","CanÃ¢â‚¬â„¢t say"]'::jsonb, 0, 'As per Section 9 of Companies Act, 2013, the Company is combination of separate 3 pillar i.e. Investor, Management and Auditor. Investor invest the money which is used by management to run business and auditor checked whether money is being properly used or not'),
(53, 'The Company is an artificial judicial person, it is not a natural person. True or False.', '["True","False","Partly True","CanÃ¢â‚¬â„¢t say"]'::jsonb, 0, 'As per Section 9 of Companies Act, 2013, Company is created by human, itÃ¢â‚¬â„¢s not natural'),
(54, 'The Company has to right to enter into contract on its own name. True or False', '["True","False","Partly True","Partly False"]'::jsonb, 0, NULL),
(55, 'The term Public Company is defined under which Section of the Companies Act, 2013?', '["Section 2 (71)","Section 2 (10)","Section 2 (4)","Section 2 (3)"]'::jsonb, 0, NULL),
(56, 'Everything which is done in the company will be known by the name of the company?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, NULL),
(57, 'Which Company do not have capital clause?', '["Limited by shares","Limited by Guarantee","Both a and b","None of the above"]'::jsonb, 1, NULL),
(58, 'There can be a transfer of property from a company to the ------------ & vice- versa.', '["Member","Employee","Promoter","None of the above"]'::jsonb, 0, NULL),
(59, 'The Limited company have subtypes namely ------------', '["Company limited by shares","Company limited by Guarantee","Company limited by shares as well as Guarantee","All of above"]'::jsonb, 3, NULL),
(60, 'A person can be a member, director, employee and creditor of the company same time?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'A person can be a member, director, employee and creditor of the company at the same time'),
(61, 'Mr. A is a director of the ABC Limited, he wants to hold secured debentures from company. Can he do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'A person can be a member, director, employee and creditor of the company at the same time'),
(62, 'A company is not an agent of members or directors. True or False.', '["True","False","Partly True","CanÃ¢â‚¬â„¢t say"]'::jsonb, 0, NULL),
(63, 'Mr. Kiran is a director and employee of the KBC Limited, he wants to purchase the equity shares of the company. Whether he can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'A person can be a member, director, employee and creditor of the company at the same time'),
(64, 'M. K is an engineer, formed manufacturing company. The name of the company is KE Ltd. Mr. K was also an employee having a contract of compensation with KE Ltd. in case of damage to him or his life. At one day he met with accident during testing of machine and he died, whether wife of the K can receive the compensation from the company?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'There was valid contract between the company and Mr. K'),
