-- ==================== CHAPTER 3 ====================

-- Chapter 3: Prospectus and Allotment of Securities
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 3, 'Prospectus and Allotment of Securities', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'Section 23 of the Companies Act, 2013 deals with the ways a Public company can issue its securities namelyÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["To public through Prospectus(IPO and FPO)","Private Placement","By right or bonus issue","All of the above"]'::jsonb, 3, 'As per Section 23(1) of the Companies Act, 2013.'),
(2, 'M/s ABC Ltd., is a Public Limited company desires to issue its securities. States the ways a company can issue its securities?', '["To public through Prospectus(IPO and FPO)","Private Placement","By right or bonus issue","All of the above"]'::jsonb, 3, 'As per Section 23(1) of the Companies Act, 2013.'),
(3, 'Section 23 of the Companies Act, 2013 deals with the ways a Private company can issue its securities namelyÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["By right issue","By bonus issue","Private Placement","All of the above"]'::jsonb, 3, 'As per Section 23(2) of the Companies Act, 2013.'),
(4, 'M/s ABC Pvt. Ltd., is a Private Limited company desires to issue its securities. States the ways a Private company can issue its securities?', '["By right issue","By bonus issue","Private Placement","All of the above"]'::jsonb, 3, 'As per Section 23(2) of the Companies Act, 2013.'),
(5, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Company is prohibited from access to the public in raising its capital.', '["Public company","Private company","All of the above","None of the above"]'::jsonb, 1, 'As per Section 2(68) of the Companies Act, 2013, Private company prohibits any invitation to the public to subscribe for any securities for any securities of the Company.'),
(6, 'In case of Listed Company or a company who propose to get its securities listed, issue shall be governed by the Companies Act, 2013 as well as provision of SEBI Act, 1992. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'Section 24 of the Companies Act, 2013, Powers of SEBI to regulate Issue & Transfer of Securities.'),
(7, 'Can issue of Prospectus compulsory for a company?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 23(1) of the Companies Act, 2013, it is issued by a public company which is seeking to raise the required funds from the public by means of issue of shares and debentures. It is not necessary for every company to file a prospectus. ... Private companies are not required to file a prospectus.'),
(8, 'M/s ABC Pvt. Ltd., is a Private Limited company desires to issue prospectus for public offer. Whether Company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 23(2) of the Companies Act, 2013, a Private Company is prohibited from inviting the public for subscription of its shares, i.e. a Private Company cannot issue Prospectus, whereas a Public Company is free to invite public for subscription i.e., a Public Company can issue a Prospectus.'),
(9, 'Any document by which the offer for sale to the public is made, where a company allots or agrees to allot any securities of the company with a view to all or any of those securities being offered for sale to the public, shall be Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Prospectus issued by the company', '["Deemed Prospectus","Red herring Prospectus","Shelf Prospectus","Abridged Prospectus"]'::jsonb, 0, 'As per Section 25 of the Companies Act, 2013'),
(10, 'Deemed Prospectus shall be signed byÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["By 2 directors in case of Company and by not less than one- half of the partners in case of Firm","By 3 directors in case of Company and by not less than one of the partners in case of Firm","By 1 directors in case of Company and by not less than 2 of the partners in case of Firm","By 2 directors in case of Company and by not less than one of the partners in case of Firm"]'::jsonb, 0, 'As per Section 25 of the Companies Act, 2013'),
(11, 'States the non-applicability of Section 26 of the companies Act, 2013', '["Not applicable to","is not applicable to issue of shares or","Both a and","None of the existing shareholders or debentures debentures of similar nature which are already issue by the company b above"]'::jsonb, 2, 'As per Section 26 of the Companies Act, 2013, Contents of prospectus.'),
(12, 'States the procedure of alteration of contents of prospectus?', '["General meeting Ã¢â‚¬â€œ Special resolution shall be passed","The prescribed details of the notice shall be published in two newspaper, one in English and other vernacular language, circulating in the city in which the registered office of the company is situated","Both a and b","None of the above"]'::jsonb, 2, 'As per Section 27 of the Companies Act, 2013, Alteration of contents of prospectus.'),
(13, 'Restriction on use of money through prospectus shall not be used For buying, trading or otherwise dealing in equity shares of any other listed company. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, '2 nd Proviso to subsection 1 of the Section 27 of the Companies Act, 2013, restriction on use of money raised.'),
(14, 'State the Section of companies Act, 2013 for alteration of content of prospectus.', '["Section 27","Section 25","Section 26","Section 28"]'::jsonb, 0, NULL),
(15, 'State the circumstances, under which issue of prospectus is not necessary under the provision of the Companies Act, 2013', '["Private Placement through issue a Private Placement letter","Securities are offered to existing holders under a right issue","Securities are offered to existing holders under a bonus issue","All of the above"]'::jsonb, 3, 'Section 23 and 25 of the Companies Act, 2013.'),
(16, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..is a public offer made by a company to subscribe for its securities by the public through prospectus.', '["Initial Public offer/ Further Public Offer","Offer for sale","Private Placement","Right issue"]'::jsonb, 0, NULL),
(17, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ prospectus means a prospectus in which a permanent or constant information of earlier year is given for numerous number of issue over such period.', '["Deemed Prospectus","Red herring Prospectus","Shelf Prospectus","Abridged Prospectus"]'::jsonb, 2, 'Section 31 of the Companies Act, 2013'),
(18, 'Shelf Prospectus is valid for Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Years.', '["1 Year","2 Year","3 Year","5 Year"]'::jsonb, 0, 'Section 31 of the Companies Act, 2013, validity of Shelf Prospectus is one year.'),
(19, 'Section 29 of the Companies act, 2013, dematerialization is mandatory for every company making public offer. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'As per section 29(1) of the Companies act, 2013, every company making Initial public offer must go for Dematerialization.'),
(20, 'M/s ABC ltd., is a Public Limited company desires to go for an Initial public offer. Whether Dematerialization is mandatory for such company?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per section 29(1) of the Companies act, 2013, makes it mandatory every company making Initial public offer.'),
(22, 'If a company or any other person has received application for allotment of securities along with advance payment then the company or any other person shall intimate the changes to such applicant, and an option to withdraw their application shall be given to such applicants and if such applicants desire to withdraw their application, all monies received them shall be refunded within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Days.', '["20 days","10 days","30 days","15 days"]'::jsonb, 3, 'Section 31 of the Companies act, 2013'),
(24, 'Mr. Ram applies for share on the basis of a prospectus which contain misstatement. The shares are allotted to him, who afterwards transfer them to Mr. Shyam. Can Mr. Shyam bring an action for a rescission on the ground of misstatement?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 37 of the Companies act, 2013, Mr. Shyam cannot bring an action for rescission of the contract to buy shares from Mr. Ram on the ground of misstatement. A suit may be filed or any other action may be taken under Section 34 or Section 35 or Section 36 only by any person, group of persons or any association of persons affected by any misleading statement or the inclusion or omission of any matter in the prospectus.'),
(25, 'No allotment of any securities of a company offered to the public for subscription shall be made unlessÃ¢â‚¬Â¦.', '["The amount stated in the prospectus as the minimum amount has been subscribed","the sum payable on application for the amount so stated have been paid to and received by the company by cheque or other instrument","Both a and b","a or b"]'::jsonb, 2, 'Section 39 of the Companies Act, 2013, no allotment without subscription'),
(26, 'Amount payable on application on every security shall beÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Not less than 5 % of nominal amount","such other amount or % as specified by SEBI","a or b","None of the above"]'::jsonb, 2, 'Section 39 of the Companies Act, 2013, Minimum application money to be paid'),
(27, 'If Company fails to issue regular prospectus, if any person is not satisfied with Abridged Prospectus and he can demand regular prospectus from the Company. State the penalty for non-compliance.', '["Rs. 50,000/-","Rs. 1,00,000/-","Rs. 5,00,000","None of the above"]'::jsonb, 0, 'Section 33 of the Companies Act, 2013.'),
(28, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Means a prospectus contained summary of original Prospectus so as to save cost and time.', '["Deemed Prospectus","Red herring Prospectus","Shelf Prospectus","Abridged Prospectus"]'::jsonb, 3, 'Section 33 of the Companies Act, 2013.'),
(29, 'It is compulsory for every company to issue Abridged Prospectus with Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["Regular Prospectus","Application Form","Red herring Prospectus","Shelf Prospectus"]'::jsonb, 1, 'Section 33 of the Companies Act, 2013.'),
(30, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ Prospectus is estimated worth of the company in open market', '["Deemed Prospectus","Red herring Prospectus","Shelf Prospectus","Abridged Prospectus"]'::jsonb, 1, 'Section 32 of the Companies Act, 2013.'),
(31, 'Red herring Prospectus shall be filed by the company with the ROC at least Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. days prior to the opening of the subscription and the offer', '["10 days","20 days","30 days","60 days"]'::jsonb, 0, 'Section 33 of the Companies Act, 2013, time limit for filing with ROC.'),
(32, 'The company shall file actual prospectus with ROC & SEBI containing details ofÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Total capital raised","Closing and final price of shares","Any other details not included in Red Herring Prospectus","All of the above"]'::jsonb, 3, 'Section 33 of the Companies Act, 2013, issue of actual prospectus.'),
(33, 'Public will place bidding on the basis of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Prospectus in given price band and bidding will be converted into offer.', '["Deemed Prospectus","Red herring Prospectus","Shelf Prospectus","Abridged Prospectus"]'::jsonb, 1, 'Section 33 of the Companies Act, 2013.'),
(34, 'Any changes between Red Herring Prospectus and a Prospectus shall be highlighted as Ã¢â‚¬ËœvariationsÃ¢â‚¬â„¢ in actual Prospectus. True or False.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Section 33 of the Companies Act, 2013, Red Herring Prospectus shall carry the same obligations as applicable to the actual Prospectus. If found any changes between them, same shall highlighted.'),
(35, 'Mr. Ram is not satisfied with Abridged Prospectus of M/s ABC Ltd. He demand the regular prospectus from M/s ABC Ltd. Whether he can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per section 33 of the companies act, if any person is not satisfied with Abridged Prospectus and he can demand regular prospectus from the Company. It is the duty of the company to provide the same.'),
(36, 'The Article of Association of ABC Ltd. contained a provision that up to 4% of issue price of the shares may be paid as underwriting commission to the underwriters. The Board of directors of ABC Ltd. decided to pay 5% underwriting commission. State the validity.', '["Valid","Invalid","Neutral","CanÃ¢â‚¬â„¢t say"]'::jsonb, 1, 'As per Rule 13 of Companies(Prospectus and allotment of securities) Rules, 2014 the rate of commission paid or agreed to be paid shall not exceed 5% of the price at which the shares are issued or a rate authorized by the article, whichever is less.'),
(37, 'After allotment, a Return of allotment in Form PAS 3 containing details shall be filed with ROCÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["List of security holder","Full name and address of security holder","Number of securities allotted and other relevant information prescribed","All of the above"]'::jsonb, 3, 'Section 42 of the Companies Act, 2013.'),
(38, 'The underwriting commission on shares must not exceedÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["2.0 % of the issued price of shares","2.5 % of the issued price of shares","5.0 % of the issued price of shares","5.5 % of the issued price of shares"]'::jsonb, 2, 'As per Rule 13 of Companies (Prospectus and allotment of securities) Rules, 2014'),
(39, 'If a company does not receive the minimum subscription, it should refund money received from applicants within 120 days of issue of prospectus. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 1, 'As per Section 39(3) of the Companies act, 2013 if the amount of subscription has not received within 30 days from prospectus date then the amount received under sub section (1) shall be returned within 15 days from the closure of the issue'),
(40, 'If amount of a minimum subscription has not received within 30 days from prospectus date or any other period prescribed by SEBI, then amount received shall be returned within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Days from the closure of issue.', '["30 days","15 days","60 days","120 Section 39(1) of the Companies act, 2013"]'::jsonb, 1, 'Section 39(1) of the Companies act, 2013'),
(41, 'The underwriting commission on Debenture must not exceedÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["2.0 % of the issued price of shares","2.5 % of the issued price of shares","5.0 % of the issued price of shares","5.5 % of the issued price of shares"]'::jsonb, 1, 'As per Rule 13 of Companies (Prospectus and allotment of securities) Rules, 2014'),
(42, 'ABC Ltd. offered to the public for subscription but the minimum subscription has not been received within 30 days from prospectus date, in how many days company can returned the amount received?', '["30 days","15 days","60 days","120"]'::jsonb, 1, 'Section 39(1) of the Companies act, 2013.'),
(43, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Is an instrument through which Indian company can issue its shares across the globe?', '["Global Depository Receipt","American Depository Receipt","Indian Depository Receipt","None of the above Section 41 of the Companies act, 2013."]'::jsonb, 0, 'Section 41 of the Companies act, 2013.'),
(44, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Is an instrument through which Indian company can issue its shares in America?', '["Global Depository","American Depository","Indian Depository","None of Receipt Receipt Receipt the above"]'::jsonb, 1, 'Section 41 of the Companies act, 2013.'),
(46, 'A Private placement offer or invitation shall not be made, in one financial year, to more than Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Persons and not more than Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦persons in aggregate in a financial year.', '["50, 200","100, 200","50, 100","100, 500"]'::jsonb, 0, 'Section 42 of the Companies act, 2013, condition for Private Placement.'),
(47, 'Can a Public Company make Private placement?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Private placement is a common method of raising business capital through offering equity shares. Private placements can be done by either private companies wishing to acquire a few select investors or by publicly traded companies as a secondary stock offering'),
(48, 'The Company shall not accept any cash towards subscription of securities?', '["Yes","No","Partly Yes","Partly No Section 42 of the Companies Act, 2013, cash not to be accepted towards subscription."]'::jsonb, 0, 'Section 42 of the Companies Act, 2013, cash not to be accepted towards subscription.'),
(49, 'XYZ Pvt. Ltd. is a Private Limited Company desires to issue shares through private placement to 35 group of persons. At the same time Company also offered securities to 10 employee under ESOP u/s 62(1)(b). While calculating number of persons for private placement under section 42 of the companies Act, 2013, can company also considered numbers of employees to whom the securities has been offered under ESOP u/s 62(1)(b)?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 42 of the Companies Act, 2013, Qualified Institutional buyer and employees to whom the securities has been offered under ESOP u/s 62(1)(b) are excluded while computing the number of persons.'),
(50, 'ABC Pvt. Ltd. is a Private Limited Company desires to issue shares through private placement to 50 group of persons. At the same time Company also offered securities to 2 Qualified Institutional buyer. While calculating number of persons for private placement under section 42 of the companies Act, 2013, can company also considered numbers of Qualified Institutional buyer to whom the securities has been offered?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 42 of the Companies Act, 2013, Qualified Institutional buyer and employees to whom the securities has been offered under ESOP u/s 62(1) (b) are excluded while computing the number of persons.'),
(51, 'No further offer under section 42 of the Companies Act, 2013 shall not be made unless the earlier offer or invitation, if any Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["the allotment have been completed","such offer or invitation has been withdrawn or abandoned by the company","Either a or b","None of the above"]'::jsonb, 2, 'Section 42 of the Companies Act, 2013, no further offer pending the earlier offer.'),
(52, 'MNS Pvt. Ltd. is a Private Limited company desires to offer shares under private placement but the earlier allotment of company have not been completed. Whether Company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 42 of the Companies Act, 2013, company shall made offer after completion of earlier allotment or such earlier offer or invitation has been withdrawn or abandoned by the company'),
(53, 'Any offer which is in contravention to Section 42 of the Companies Act, 2013 shall be treated as public offer?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Section 42 of the Companies Act, 2013, consequences of contravention of section.'),
(54, 'MNS. Ltd. is a Public Limited company desires to offer shares 60 persons under private placement. Whether Company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 42 of the Companies Act, 2013, A Private placement offer or invitation shall not be made, in one financial year, to more than 50 Persons and not more than 200 persons in aggregate in a financial year. Any offer which is in contravention to Section 42 of the Companies Act, 2013 shall be treated as public offer'),
(55, 'Issue of offer letter to investor under private placement in Form numberÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["PAS 1","PAS 2","PAS 3","PAS 4"]'::jsonb, 3, 'Section 42 of the Companies Act, 2013 and Companies (Prospectus And Allotment of Securities) Rules, 2014'),
(56, 'Under Private Placement, if the application money not refunded, company shall pay interest 12% p.a. from the end of Ã¢â‚¬Â¦. Days.', '["30 days","40 days","60 days","90 days"]'::jsonb, 2, 'Section 42 of the Companies Act, 2013.'),
(57, 'Under Private Placement, if the application money not refunded, company shall pay interest Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. p.a. from the end of 60 Days.', '["10%","12%","20%","30%"]'::jsonb, 1, 'Section 42 of the Companies Act, 2013.'),
(58, 'MNS. Ltd. is a Public Limited company, is failed to allot securities under Private Placement within 60 days from the date of submission application money. Whether it is necessary for company to refund the application money along with interest?', '["Yes","No","Only application money","Only interest"]'::jsonb, 0, 'Section 42 of the Companies Act, 2013, if the application money not refunded, company shall refund application money along with interest of 12% p.a.'),
(59, 'Company shall maintain records of Private Placement in Form numberÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["PAS 4","PAS 2","PAS 3","PAS 5"]'::jsonb, 3, 'Section 42 of the Companies Act, 2013 and Companies (Prospectus And Allotment of Securities) Rules, 2014'),
(60, 'Company shall file return of Private Placement in Form numberÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["PAS 4","PAS 2","PAS 3","PAS 5"]'::jsonb, 2, 'Section 42 of the Companies Act, 2013 and Companies (Prospectus And Allotment of Securities) Rules, 2014')
