-- ==================== CHAPTER 4 ====================

-- Chapter 4: Share Capital and Debentures
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 4, 'Share Capital and Debentures', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'M/s ABC Pvt. Ltd, is a Private Limited Company is desirous to issue prospectus for inviting the public for subscription of its issue. Can the Company do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'A Private Company is prohibited from inviting the public for subscription of its shares, i.e. a Private Company cannot issue Prospectus , whereas a Public Company is free to invite public for subscription i.e., a Public Company can issue a Prospectus .'),
(2, 'Which rights are attached with Equity shares with Differential rights?', '["Different dividend","Different face value","Different voting rights and Different advantages and disadvantages etc.","All of the above"]'::jsonb, 3, NULL),
(3, 'The company will repay the amount of share capital to the holders of shares after the fixed period or even earlier at the discretion of the company is called asÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. shares', '["Redeemable Preference shares","Convertible Preference shares","Participating Preference shares","Non - Participating Preference shares"]'::jsonb, 0, 'As per Section 55(2) Companies Act, Issue Preference shares which are liable to be redeemed within a period not exceeding 20 years from the date of their issue subject to such conditions as may be prescribed., but in case of infra structure company, Period of redemption is period exceed 20 years but not 30 years as specified under schedule VI.'),
(6, 'Share certificates are to be issued by a company withinÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Months.', '["one month after allotment","Two months after allotment","Six months after allotment","Three months after allotment"]'::jsonb, 1, 'Section 46 of the companies Act, 2013 read with Rule 5,6 & 7 of the Companies(Share Capital & Debentures)Rules, 2014'),
(8, 'A transferee become a member of the Company when the instrument of transfer is submitted with the company. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 1, 'Section 56 of the companies Act, 2013, A transferee become a member of the company when the transfer is registered with the company.'),
(9, 'A share warrant is a bearer instrument and the bearer is entitled to the shares specified in the share warrant. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'In terms of the com panies Act, 2013, A share warrant is a bearer documents stating that the holder is entitled to certain number of shares specified therein.'),
(17, 'Can a Private Limited Company issue preference shares?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Companies Act, 2013, an Indian Private Limited Company or Limited Company can issue preference shares , if authorized by the articles of association of the company . All preference shares issued by a company in'),
(18, 'Can a Private Limited Company issue debenture as per Companies Act, 2013?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 71 of the Companies Act, 2013, Issue of debentures is governed by the Companies Act , 2013 , SEBI regulations and RBI regulations. The Companies Act , 2013 allows both private and public'),
(19, 'M/s XYZ Ltd., is a public limited company desires to issue debenture with voting rights, Can company do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 71 (2) of the Companies Act, 2013, issue of debentures which carry any voting'),
(20, 'Can a Private Limited Company issue prospectus?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'A Private Company is prohibited from inviting the public for subscription of its shares, i.e. a Private Company cannot issue Prospectus , whereas a Public Company is free to invite public for subscription i.e., a'),
(21, 'As per Section 44 of the Companies Act, 2013, Shares, debenture and other interest of any manner in a company shall be movable property in the manner provided be the article of the company?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Goods means every kind of movable property includes stock and shares which are agreed to be severed before sale or under the contract of sale.'),
(22, 'Whether the mandatory requirement of registration shall be applicable to shares in D - mat form also?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'The mandatory requirement are not applicable where both transferor and transferee have D mat accounts. That is why the words Ã¢â‚¬Å“other than the records of a depositoryÃ¢â‚¬Â have been added to Subsection (1) of Section 56 of the Companies act, 2013.'),
(23, 'Who has the authority to declare dividends?', '["Board committee","Board of Directors","Creditors","Members"]'::jsonb, 1, 'When the board of directors makes such a decision and declares a dividend fo r payment to stockholders, the retained earnings account on the company''s balance sheet is reduced by the amount of the declared dividend. The retained earnings is an account of equity that shows the net balance of a company''s earnings.'),
(24, 'Which of the following companies shall not buy back its own securities unless the consequent reduction of share capital is effected under the Section 67 of the companies Act, 2013?', '["Limited by shares (Private and Public)","Limited by guarantee","Unlimited co.","Both a and b"]'::jsonb, 3, 'As per Sec tio n 67(1) of the compa nies Act, 2013'),
(25, 'M/s XYZ Ltd., is a Public Limited Company desires to give to Mr. Ramnath a loan of Rs. 10 Crore for purchase of its own shares. Whether Company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 67(2) of the companies Act, 2013, a Public Limited Company shall not, whether directly or indirectly give to any person a loan, guarantee, security or any other financial assistance for purchase of its own shares or shares in its Holding Company'),
(26, 'M/s ABC Pvt. Ltd., is a Private Limited Company desires to give to Mr. Shyam a loan of Rs. 5 Crore for purchase of its own shares. Whether Company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 67(2) of the companies Act, 2013 (not to finance others for buyback of own securities) is applicable to public Company only.'),
(27, 'M/s MNC Ltd., is a Public Limited Company desires to give to Mr. Tukaram a guarantee for his loan with Bank OF Maharashtra of Rs. 50 Lakhs for purchase of its own shares. Whether Company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 67(2) of the companies Act, 2013, a Public Limited Company shall not, whether directly or indirectly give to any person a loan, guarantee, security or any other financial assistance for purchase of its own shares or shares in its Holding Company'),
(28, 'Every buyback shall be completed within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Years from the date of passing of special resolution/Board resolution.', '["2 years","1 Year","5 Years","3 Years"]'::jsonb, 1, 'As per Section 68(4) of the companies Act, 2013, time limit for completion of buy back.'),
(29, 'M/s ABC Limited desires to buy back its shares. Company passed the special resolution at 1 st January, 2016. As per Section 68(4) of the companies Act, 2013, up to which date company need to be completed the process of buy back?', '["5 th January, 2016","30 th December, 2017","30 th September, 2016","None of the above"]'::jsonb, 1, 'As per Section 68(4) of the companies Act, 2013, Every buyback shall be completed within 1 Year from the date of passing of special resolution/Board resolution.'),
(30, 'The Securities Premium account cannot be utilizedÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["In writing off the preliminary expenses of the company","In writing off the expenses of commission paid on issue of share of the company","For redemption of redeemable preference shares","In providing for the premium payable on the redeemable preference shares"]'::jsonb, 2, 'Section 52 of the companies Act, 2013'),
(31, 'Only Public Limited Companies have the right to issue share warrant. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, NULL),
(32, 'All the Companies limited by shares irrespective of public or Private have the right to issue share Certificate .', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'Section 46 of the Companies Act, 2013'),
(35, 'If any share certificate be worn out, defaced, mutilated or torn or if there be no further space on the back for endorsement of transfer, then upon production and surrender thereof to the company, duplicate share certificate shall be issued on payment of Rs. 20 for each certificate?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Section 46 of the Companies Act, 2013'),
(36, 'Mr. Ram is a member of a company. He applied to the company regarding duplicate share certificate after having an original share certificate. Whether he can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 46 of the Companies Act, 2013, shareholder can apply for duplicate share certificate If his share certificate be worn out, defaced, mutilated or torn or in case it is lost or destroyed.'),
(39, 'State the conditions for variation of Rights of any class.', '["Consent in writing of the holders of not less than 75% of the issued shares of that class is obtained or Special resolution is passed at a separate meeting of holders of that meeting","Authorized by Memorandum of Association and Article of Association or if no such Authorization is there , as per the terms of issue of that class","variation by one class of shareholders should not affect the rights of any class of shareholders, if it affects then Special resolution of that class of shareholders","All of the above"]'::jsonb, 3, 'Section 48 of the Companies Act, 2013 states Variation of shareholders Right.'),
(40, 'Number of dissenting shareholders to the variation or in favour of the special resolution for the variation, should not be less than Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦% of the issued shares of that class', '["10%","20%","25%","None of the above"]'::jsonb, 0, 'Section 48 of the Companies Act, 2013 states Variation of shareholders Right.'),
(41, 'M/s Sunstar Ltd. is authorized by its Article of Association to accept whole or any part of the amount of remaining unpaid calls from any member although no parts of that amount has been called up. A, a shareholder of the Sunstar Ltd. deposits in advance the remaining amount due on his shares without any calls made by Sunstar Ltd. State the Section of the Companies Act, 2013?', '["Section 49","Section 50","Section 51","Section 52"]'::jsonb, 1, 'Section 50 of the Companie s Act, 2013 states call'),
(42, 'Mr. A, a shareholder of the Moonstar Ltd. wants to deposits in advance the remaining amount due on his shares without any calls made by Moonstar Ltd. Whether Moonstar Ltd. can accept his advance share amount?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 50 of the Companies Act, 2013, a company can accept calls in advance i.e. without making a call. For that Company required'),
(43, 'No concept of call for bonds and debenture as per Companies Act, 2013?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Bonds and Debenture s are debts, so they are always fully paid up. As per Section 49 of the Companies Act, 2013, uniform calls'),
(44, 'M/s Sunstar Ltd. desires to issue partly paid bonds and debentures. Whether company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Bonds and Debentures are debts, so they are always fully paid up. As per Section 49 of the Companies Act, 2013, uniform calls for'),
(45, 'Preference shares are always fully paid up?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 49 and 55 of the Companies Act, 2013, preference shares are partly paid also but shall be paid up before redemption of shares.'),
(46, 'M/s Sunstar Ltd. desires to issue partly paid preference shares. Whether company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 49 and 55 of the Companies Act, 2013, preference shares are partly paid up also but shall be paid up before redemption of shares.'),
(47, 'M/s Sunstar Ltd. desires to issue equity shares at discount. Whether company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 53 of the Companies Act, 2013, a company shall not issue shares (except sweat equity shares u/s 54) at a discount. Any issue at a discount price by a company shall be void.'),
(49, 'M/s XYZ Ltd. is desirous to utilized Capital Redemption Reserve for the purpose of issuing partly paid bonus shares to the members. Whether company can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per section 55(4) of the Companies Act, 2013 Capital Redemption Reserve shall be utilized only for the purpose of issuing Fully paid bonus shares to the members'),
(50, 'State the conditions for redemption of Unredeemed Preference shares?', '["Replacing old Preference shares with new","Special resolution of such class of shareholders","Approval of Tribunal obtained","All of the above"]'::jsonb, 3, 'As per section 55(4) of the Compan ies Act, 2013 Capital Redemption Reserve shall be utilized only for the purpose of issuing Fully paid bonus shares to the members'),
(51, 'As per Section 62 of the Companies Act, 2013, further issue shall be offered toÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["Existing shareholders through a letter of offer","Employees under ESOP","Any person either for cash or kind","All of the above"]'::jsonb, 3, 'As per Section 62(1) of the Companies Act, 2013'),
(52, 'Time limit given to existing shareholders to accept the offer of right issue shall not be less than Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Days but not more thanÃ¢â‚¬Â¦Ã¢â‚¬Â¦.. days of offer', '["15 and 30","15 and 20","5 and 30","10 and 60"]'::jsonb, 0, 'As per Section 62(1) of the Companies Act, 2013, it is one of the condition to be complied with for further issue to existing shareholders.'),
(53, 'M/s Sunstar Ltd. is given offer to employees of the company for right issue. Mr. Ram is employee of company accept the offer of company but later he realize that he has not able to take that shares then he renounce his shares to Mr. Shyam. Whether Mr. Ram can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 62(1) of the Companies Act, 2013, the shareholders will have right of renouncement and same will be mentioned in the notice.'),
(54, 'Fully paid up shares shall be issued by a company out of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["its free reserves","the securities Premium account","the capital redemption reserve","All of the above"]'::jsonb, 3, 'As per Section 6 3(1) of the Companies Act, 2013, sources of the Issue of Bonus shares.'),
(55, 'The bonus shares shall not issue in lieu of dividend. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'As per Section 63(3) of the Companies Act, 2013, Bar on Issue of shares in lieu of dividend.'),
(56, 'No issue of bonus shares shall be made by capitalizing reserves created by the revaluation of assets?', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'As per Section 63(1) of the Companies Act, 2013, Bar on Issue of shares in lieu of dividend'),
(59, 'S Ltd. has announced to issue of dividend to all shareholders. Due to change in plan, Company decided to issue bonus share instead of dividend. Can the Company do so?', '["Yes","No","Approval of shareholders","Approval of BOD"]'::jsonb, 1, 'As per Section 63(2) of the Companies Act, 2013, the bonus shares shall not be issued in lieu of dividend'),
(60, 'M/s ABC Ltd. has enough amounts in revaluation reserve. Can the Company issue bonus shares out of it?', '["Yes","No","Approval of shareholders","Approval of BOD"]'::jsonb, 1, 'As per Section 63(1) of the Companies Act, 2013, no bonus shares shall be made by capitalizing reserve created by the revaluation of assets.'),
(61, 'XYZ Ltd proposes to issue bonus shares to all shareholders. But the Company has failed to pay gratuity to its shareholders since 5 years. Can the Company make such issue?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 63(2) of the Companies Act, 2013, one of the condit ion for issue of bonus shares is company has not defaulted in payment of statutory dues like PF, Gratuity etc.'),
(62, 'XYZ Ltd has a huge amount of reserve in store and proposes to issue bonus shares to the shareholders. Company had not paid interest since post 3 years. Is the Company eligible to issue Bonus?', '["Yes","No","6 m + SR","Application of SEBI"]'::jsonb, 1, 'As per Section 63(2) of the Companies Act, 2013, one of the condition for issue of bonus shares is company has not defaulted in payment of interest or principal in respect of Fixed deposit or debt securities.'),
(63, 'XYZ Ltd has a huge amount of reserve in store and proposes to issue bonus shares to the shareholders. Company had not paid interest since post 3 years. Is the Company eligible to issue Bonus?', '["Yes","No","6 m + SR","Application of SEBI"]'::jsonb, 1, 'As per Section 63(2) of the Companies Act, 2013, one of the condition for issue of bonus shares is company has not defaulted in payment of interest or principal in respect of Fixed deposit or debt securities.'),
(64, 'Sweat equity shares allotted to employees shall be locked it forÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["6 Months","1 Year","2 Years","3 Years"]'::jsonb, 1, 'As per Section 54 of the Companies Act, 2013, condition for issue of Sweat equity shares.'),
(65, 'What is the cooling period after the buyback of securities for the same type of securities -', '["1 year from the date of buy back","6 months from the date of buyback","No such cooling period as per Companies Act, 2013 but exists as per companies act, 1956","2 years from the date of buyback"]'::jsonb, 1, 'As per Section 68 companies act, 2013, there must be a cooling period of at least 6 months for the'),
(66, 'A company wants to give loan of Rs. 750000 to Mr. Ram, its employee for purchase of his shares. Salary of Mr. Ram is Rs. 45000 per month -', '["Company cannot give financial assistance to buy its own shares","Company can give financial assistance up to Rs. 600000 only being Rs. 50000 per month is the limit as said by companies Act.","Company can give up to Rs. 270000 only.","Company can give up to Rs. 540000 only."]'::jsonb, 2, 'A company can give loan to its employees up to amount not exceeding 6 monthsÃ¢â‚¬â„¢ salary of the particular employee. Here in this case salary of Mr. Ram is Rs. 45000 per month. So maximum permissible amount will be Rs.270000.'),
(67, 'In the case of transfer or transmission of shares, company need to deliver certificates of the securities transferred or t ransmitted within a period of -', '["1 month from the receipt of instrument of transfer","2 month from the receipt of instrument of transfer","1 month from the date when shares are actually transferred or transmitted.","2 month from the date when shares are actually transferred or transmitted."]'::jsonb, 0, 'Ever y company shall unless prohibited by any court, law or tribunal should deliver the certificates of securities transferred or transmitted 1 month from the date of receipt of instrument of'),
(68, 'An exception to the rule that no company can provide financial assistance for purchase or subscription of its own s hares is -', '["Financial assistance is by a banking company in ordinary course of business","Financial assistance is given at an higher rate of interest","Financial assistance is given to the related parties at an higher interest rate","Financial assistance can be given to Board of directors to control the minority interest."]'::jsonb, 0, 'Banking company can give Financial assistance in its ordinary course of business at'),
(69, 'Redemption of shares can be made for only..............', '["Bonus shares","Right shares","Fully paid shares","Partly paid shares"]'::jsonb, 2, 'No preference shares can be redeemed unless they are fully paid as per Section 55 of Companies Act, 2013.'),
(70, 'In case of allotment of debenture, company need to deliver certificate of debentu re allotted within a period of Ã¢â‚¬Â¦..', '["6 months from the date of application for debentures","6 months from the date of allotment","2 months from the date of allotment","2 months from the date of application for debentures"]'::jsonb, 1, 'Every company shal l unless prohibited by any court, law or tribunal should deliver the certificates of debentures allotted 6 months from the date of allotment of debentures.'),
(73, 'Shares and debentures of a company are -', '["Movable property","immovable property","both of them","Movable property only when they are maintained in physical form and not in electronic form."]'::jsonb, 0, 'As per section 44 of the companies Act, 2013, shares and debentures or interest thereon of any member in the company shall be a movable property irrespective of the truth that they are held in electronic or physical form.'),
(74, 'The capital which is authorized by the memorandum of the company to be the maximum amo unt of share capital is called -', '["authorized share capital of the company","Nominal share capital of the company","Paid up share capital of the company","Both a and b"]'::jsonb, 3, 'As per sec. 2(8) of the companies Act, 2013, authorized or Nominal capital is the maximum amount of share capital that a company can issue.'),
(75, 'In case of allotment of shares, company need to deliver certificates of the securities allotted within a period of -', '["2 months from the date of allotment","2 months from the date of application","3 months from the date of application","3 months from the date of allotment"]'::jsonb, 0, 'Every company shall unless prohibited by any court, law or tribunal should deliver the certificates of securities allotted 2 months from the date of allotment in case of allotment o f any of its securities.'),
(76, 'A company can issue redeemable preference shares for a period exceeding 20 years in case of -', '["Agricultural companies","Infrastructural companies","Coal and electric projects","Hydro electric companies"]'::jsonb, 1, 'A company can issue redeemable preference shares with a term exceeding 20 years in case of Infrastructural projects however such term should not exceed 30 years.'),
(77, 'A company can issue redeemable preference shares for a period exceeding 20 years in case of Infrastructural projects provided -', '["Company pays certain amount to ROC as a fee","Company takes permission of the Central government","Company starts redeeming at least 10% from the 21 st year","Company cannot issue preference shares for a term exceeding 20 years."]'::jsonb, 2, NULL),
(78, 'Capital rede mption reserve can be used for -', '["Writing off preliminary expenses","Writing off capital losses","Writing off negative reserves","Issue of bonus shares"]'::jsonb, 3, 'Capital Redemption Reserve can be used for paying of unissued shares of the company to be issued to the members of the company as fully paid bonus shares.'),
(79, 'Letter of offer should be dispatched to shareholders within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ days after registration of ROC.', '["21 days","15 days","14 days","30 days"]'::jsonb, 0, 'As per companies act, 2013 and Rule 17(4) of the Companies (share capital and debenture) Rules, 2014 a company should dispatch letter of offer within 21 days after the filing with ROC.'),
(80, 'Buyback should be completed within a period of -', '["1 year from the date of passing special resolution","1 year from the date of passing ordinary resolution","6 months from the date of passing ordinary resolution","6 months from the date of passing special resolution"]'::jsonb, 0, 'Buyback should be completed within a period of 1 year from the date of passing special resolution for buyback.'),
(81, 'Securities Premium account can be used for-', '["In writing off the expenses related to issue of shares","for the Buyback of shares as per Sec. 68","In providing for the premium payable on the redemption of any redeemable preference shares or of any debenture of the company","All of the above"]'::jsonb, 3, 'According to Section 52 of the Companies Act, securities premium account can be used for -Issue of unissued shares as a bonus to shareholders. Writing off preliminary expenses. -In writing off the expenses related to Issue of shares. -Applying for the premium payable for the redemption of redeemable preference shares and debentures. -To buy back the shares as per sec'),
(82, 'A company cannot Issue', '["A. Redeemable preference shares","B. Irredeemable preference shares","Convertible preference shares","Non-convertible preference shares"]'::jsonb, 1, 'According to sec 55 a company cannot issue irredeem able preferenc e shares.'),
(83, 'A company can give loans to persons in the employment for the purchase or subscription of its shares-', '["Yes, can give loan up to a limit of Rs. 250000","Yes, can give loan up to an amount not exceeding 6 months salaries and wages of employees","Yes, can give loan up to an amount not exceeding 4 months salaries and wages of employees","Yes, can give loan up to a limit of 350000"]'::jsonb, 1, 'As per sec 67, company can give loan up to an amount not exceeding 6 months salaries and wages of employee for the purchase or subscription fully paid shares in the company or its holding company to be held by them by way of beneficial ownership.'),
(84, 'The pre - emptive subscription rights to buy additional securities to the e xisting shareholders is called -', '["Initial public issue","Right issue","Buy back of shares","None of the above"]'::jsonb, 1, 'As per Section 62 of the Companies Act, 2013, in case of right issue shares must be first offered to existing sha reholders before they are issued to public.'),
(85, 'As per companies act 2013, a company should maintain debt equity ratio post buyback is-', '["1:1","2:1","3:1","1:2:1"]'::jsonb, 1, 'As per Sec 68 of companiesÃ¢â‚¬â„¢ act 2013, the ratio of the aggregate of secured and unsecured debts owed by the company should not be more than twice the paid up capital and Its free reserves.'),
(86, 'The preference shares should be redeemed with in a period of-', '["Not exceeding 10 years","Not exceeding 15 years","Not exceeding 20 years","Not exceeding 5 years"]'::jsonb, 2, 'Comp any cannot issue redeemable preference shares with a term exceeding 20 years for redemption.'),
(87, 'A infrastructure project can issue redeemable preference shares f or a period exceeding 20 years -', '["A company cannot issue redeemable preference shares for a period exceeding 20 years as per the provisions of the companies act","Can Issue but the period should not be more than 30 years.","A company cannot issue redeemable preference shares for a period exceeding 30 years as per the provisions of the companies act","Can Issue but the period should not be more than 40 years"]'::jsonb, 1, 'As per sec 55 only exception to the term of issue of redeemable preference shares is Infrastructure projects. However they cannot Issue for the term excee ding 30 years.'),
(88, 'Preference Shares can be redeemed out of -', '["Reserve for debenture redemption reserve only","Profits only","Secret reserve made out of capital profits and charging low depreciation","It is the discretion of the company and its share holders"]'::jsonb, 1, 'Company can redeem Preference shares out of profits only which are available for payment of dividend.'),
(90, 'In the case of subscribers to the memorandum company need to deliver certificates of the securities allotted within a period of-', '["3 Months from the date of incorporation","3 Months from the date of commencement","2 months from the date of incorporation","2 Months from the date of commencement"]'::jsonb, 2, 'Every company shall unless prohibited by any court, law or tribunal should deliver the certificates of securities allotted within 2 months from the date of Incorporation in case of securities allotted to subscribers of memorandum.'),
(91, 'A company want to redeem 12000 shares whose face value is 10 each at a redemption value of Rs. 15 each. The company wants to redeem shares out of profits. Amount required to be transferred to CRR is-', '["120000","150000","60000","900000"]'::jsonb, 0, 'Nominal value of shares need to be transferred to CRR i.e. (12000*10= 120000'),
(92, 'When application for transfer is given by the transferor alone the transferee can give his objection within-', '["7 days from the receipt of notice from the company","15 days from the receipt of notice from the company","1 week from the receipt of notice from the company","2 week from the receipt of notice from the company"]'::jsonb, 3, 'In case of partly paid shares, when application to transfer is made by the transferor alone to make a transfer then company will iss ue a notice to the transferee. Transferee need to convey his objection within 2 weeks from the receipt of the Notice from the company.'),
(93, 'When preference shares are redeemed out of profits an amount equal to nominal value of shares shall be tr ansferred to an account called -', '["Securities premium account","Capital appreciation account","Capital redemption reserve","Capital paid-up reserve"]'::jsonb, 2, 'As per sec 55 when shares are redeemed out of profits an amount equal to nominal value of shares shall be transferred to Capital redemption reserve.'),
(94, 'Following is/are the company(ies) which Issued equity shares with differential voting rights-', '["Future Motors","Future Retails","Future Innovators","All of the above"]'::jsonb, 1, 'Tata Motors and Future Retails are the only two companies which issued Equity shares with differential voting shares.'),
(95, 'As per companies act share includes a share in the share capital and also Includes:-', '["Debentures","Stocks","Bunch of debentures","Both a and b"]'::jsonb, 1, 'As per 2(84) of companies act Share includes share in share capital and stocks. A group of shares which are traded in the share market are termed as stocks.'),
(96, 'Company cannot issue differential shares if it has been penalised during the last three years of any offence under-', '["RBI and SEBI","SEBI and SCRA","RBI, SEBI, SCRA and FEMA","Only FEMA"]'::jsonb, 2, 'Company should not have penalised for an offence under Reserve bank of India Act, 1934, The securities exchange board of India act 1992, Securities Contract Regulation Act, 1999 and Foreign Exchange Management Act 1999 in order to issue differential right shares.'),
(97, 'In order to issue Differential right shares, lt need to conduct voting through postal ballot-', '["Yes every company need to conduct postal ballot voting","Only by a company whose shares are listed in recognised stock exchange","A company which has track record of continuous profits for 3 years","A company which is defaulted in the payment of dividend to Preference share holders"]'::jsonb, 1, 'A company whose shares are Listed in recognised stock exchanges like NSE and BSE should conduct voting through postal ballot.'),
(98, 'A company need to have Consistent track record of distributable profits forÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..in order to issue Equity shares with differential voting rights.', '["Last 3 years preceding the Issue","Last 5 years preceding the Issue","Any 3 Years","Any 5 Years"]'::jsonb, 0, 'A company should have earned profits during the last three years preceding the year in which differential shares are proposed to Issue.'),
(99, 'An eligible company as per Section 76, which is accepting deposits within the limits specified under Section 180 (1) (c) may accept deposits by means ofÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["ordinary resolution","unanimous resolution","Special resolution","Special resolution and approval of Central Government"]'::jsonb, 0, NULL),
(100, 'Preference shares will carry preferential right with respect to-', '["Payment of dividend before interest to debenture holders","Payment of dividend before payment to equity Share holders In the form of dividend","Repayment of capital during the event of winding up","Both b and c"]'::jsonb, 3, 'Please note that preference shareholders have preferential right over the Equity share holders only they will not affect any others Rights.'),
(103, 'No deposits are repayable earlier thanÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.from the date of such deposits or renewal thereof', '["3 months","6 months","12 months","1 year"]'::jsonb, 0, NULL),
(104, 'What is the cooling period for the default made by the company in case of issue of shares with differential rights?', '["Six years","Three years","Five years","Seven Years"]'::jsonb, 2, 'Shares with differential rights can be issued on expiry of 5 years from the end of financial year In which default said by the act has committed.'),
(105, 'Company Should pay Interest to the Debenture holders:-', '["As and when debenture holders demand","Only in the year in which company earns profit","Irrespective of the earnings of the company, they should to make payment to Debenture holders every year","Both a and c"]'::jsonb, 2, 'Company need to pay Interest according to the terms agreed every year irrespective of the profits earned and demand from the debenture holders.'),
(106, 'Equity shares with Differential rights can be issued with Differences with respect to-', '["Voting rights","Dividend","Both voting and Dividend","Dividends or Voting rights or Otherwise"]'::jsonb, 3, 'Can be issued with difference w.r.t. Dividends or Voting rights or Otherwise.'),
(107, 'Which among the below are termed as securities as per companies act 2013?', '["Shares","Preference share","Debentures","Both a and c"]'::jsonb, 3, 'Securities includes both shares and debentures. (Please note that both preference and equity are termed as shares).'),
(108, 'Every company shall pay a penal rate of interestÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.for the overdue period in case of deposits, whether secured or unsecured, matured and claimed but remaining unpaid.', '["9% p.a.","10% p.a.","12% p.a.","18% p. a"]'::jsonb, 3, NULL),
(109, 'According to companies act 2013, shares with differential rights should not exceed-', '["Twenty five percentage of total paid up equity excluding differential right shares","Twenty six percent of total pre issue paid up equity including differential right shares","Twenty six percent of total post issue paid up equity Including differential right shares","Twenty five percentage of total paid up equity including differential right shares"]'::jsonb, 2, 'Company cannot issue more than 26% of differential right shares. This'),
(110, 'A reserve account that shall not be used by the company for any purpose other than repayment of deposits is called:', '["Debenture redemption reserve","Deposit repayment reserve","Capital redemption reserve","Free reserve"]'::jsonb, 1, NULL),
(111, 'Shares with Same voting rights and Differential voting right are the further division of-', '["Equity shares","Preferential shares","No such further division","Equity and preference put together"]'::jsonb, 0, 'Equity shares are further divided in to Shares with Same voting rights and Differential voting rights. Please note that company need to'),
(112, 'In order to Issue equity shares with differential rights, company has not defaulted in repayment of term loan or interest thereon from a-', '["Public financial institution","Scheduled bank","State level financial institution","Any of the above"]'::jsonb, 3, 'Company should not have defaulted in repayment or interest thereon on'),
(116, 'As per section 43 of the Companies Act, 2013 What are the types of share capital-', '["Equity","Debentures","Preference","Both a and b"]'::jsonb, 3, 'Share capital includes both Preferen ce and Equity shares capital.'),
(118, 'Plain Vanilla shares is the other name ofÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦shares', '["Equity shares with same voting rights","Equity shares with differential voting rights","Preference shares","Cumulative Preference shares"]'::jsonb, 0, NULL)
) as v(question_no, question, options, correct_index, hint)
where b.title = 'CA Inter Law MCQs by Darshan Khare'
on conflict (book_id, chapter_no, question_no) do nothing;


