-- Chapter 5: Acceptance of Deposit by Companies
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 5, 'Acceptance of Deposit by Companies', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'M/s ABC Ltd is a Public Limited company having net worth of Rs. 120 Cr. and turnover of Rs. 100 Cr. Whether the company is eligible to accept deposit from Public?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 76(1) of the Companies Act, 2013, a Public Company having Net worth Ã¢â€°Â¥ Rs. 100 Cr. Or Turnover Ã¢â€°Â¥ Rs. 500 Cr. are eligible to accept deposits from Public.'),
(2, 'M/s XYZ Ltd is a Public Limited company having net worth of Rs. 80 Cr. and turnover of Rs. 600 Cr. Whether the company is eligible to accept deposit from Public?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 76(1) of the Companies Act, 2013, a Public Company having Net worth Ã¢â€°Â¥ Rs. 100 Cr. Or Turnover Ã¢â€°Â¥ Rs. 500 Cr . are eligible to accept deposits from Public.'),
(3, 'A company shall issue circular to its members inviting deposits. The circular shall include a statement containingÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["Financial position of the company","The credit rating obtained by the company","Total numbers of depositors & amount due towards deposits in respect of old deposits","All of the above and such other particulars in such form and manner as may be prescribed."]'::jsonb, 3, 'Section 73(2) of the Companies Act, 2013.'),
(4, 'Any concerned depositor can make an application to theÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. If a company fails to repay the deposits or part thereof or any interest thereon.', '["Board of Directors","RBI","High Court","NCLT"]'::jsonb, 3, 'Section 73(4) of the Companies Act, 2013.'),
(5, 'A small depositor means a depositor who has deposited in a financial year a sum not exceedingÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Ten Thousand rupees","Fifteen Thousand rupees","Twenty Thousand rupees","Fifty Thousand rupees"]'::jsonb, 2, NULL),
(6, 'Company shall file circular and statement regarding public deposits with ROC within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦days.', '["10 days","20 days","30 days","45 days"]'::jsonb, 2, 'Section 73(2) of the Companies Act, 2013.'),
(7, 'A sum not less than 15% of deposits maturing in current year + in next financial year shall be deposited in Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Account at a scheduled bank.', '["Free Reserve","Securities Premium Account","Capital redemption reserve Account","Deposit Repayment Reserve Account"]'::jsonb, 3, 'Section 73(2) of the Companies Act, 2013.'),
(8, 'The Deposit Repayment Reserve Account shall be used exclusively for the purpose of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Only.', '["Redemption of preference shares","Payment of dividend","Issue of Bonus shares","Repayment of deposits only"]'::jsonb, 3, 'Section 73(5) of the Companies Act, 2013.'),
(9, 'Acceptance of deposits from public required Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Resolution of general meeting of members.', '["General Resolution","Special Resolution","unanimous Resolution","not required any resolution of members"]'::jsonb, 1, 'Section 76(1) of the Companies Act, 2013.'),
(10, 'A Public Company having net worth Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Or turnoverÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.are eligible to accept deposits from Public.', '["Net worth Ã¢â€°Â¥ Rs. 100 Cr. or Turnover Ã¢â€°Â¥ Rs. 500 Cr.","Net worth Ã¢â€°Â¥ Rs. 50 Cr. or Turnover Ã¢â€°Â¥ Rs. 500 Cr.","Net worth Ã¢â€°Â¥ Rs. 100 Cr. or Turnover Ã¢â€°Â¥ Rs. 1000 Cr.","Net worth Ã¢â€°Â¥ Rs. 50 Cr. or Turnover Ã¢â€°Â¥ Rs. 1000 Cr."]'::jsonb, 0, 'Section 76(1) of the Companies Act, 2013.'),
(11, 'If the eligible company is accepting deposits u/s 180(1) (c) then prior consent using Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Resolution of General Meeting.', '["General Resolution","Special Resolution","unanimous Resolution","not required any resolution of members"]'::jsonb, 0, 'Section 76(1) of the Companies Act, 2013.'),
(12, 'M/s XYZ Ltd is a Public Limited company having net worth of Rs. 80 Cr. and turnover of Rs. 400 Cr. Whether the company is eligible to accept deposit from members?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 73 of the Compan ies Act, 2013, every Public Company are eligible to accept deposits from members after passing special resolution in General meeting.'),
(13, 'Any person who deposits the amount but not get re-paid in specific due time either principal or interest then he can apply toÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Board of Directors","RBI","High Court","NCLT"]'::jsonb, 3, 'As per Section 73 and 76 of the Companies Act, 2013.'),
(14, 'Return of deposit to be filed with Registrar of Companies in Form NoÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Form DPT 1","Form DPT 2","Form DPT 3","Form DPT 4"]'::jsonb, 2, 'As per Section 73 of the Companies Act, 2013.'),
(15, 'Appointment of trustee for depositors in Form NoÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Form DPT 1","Form DPT 2","Form DPT 3","Form DPT 4"]'::jsonb, 1, 'As per Section 76(1) of the Companies Act, 2013.'),
(16, 'The company accepting secured deposits shall, within Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Days of such acceptance, create a charge on its assets.', '["10 days","20 days","30 days","45 days"]'::jsonb, 2, 'As per Section 76(1) of the Companies Act, 2013.'),
(17, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..is required for accepting deposits from members.', '["Ordinary Resolution at General Meeting","Special Resolution at GM","Board Resolution","Both b and c"]'::jsonb, 0, 'A company may, subject to the passing of a resolution in general meeting and subject to such rules as may be prescribed in consu ltation with the Reserve Bank of India, accept deposits from its members.'),
(18, 'No company shall accept or renew any deposit from its members, if the amount of such deposits together with the amount of other deposits outstanding as on the date of acceptance or renewal of such deposits exceedsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.per cent of the aggregate of theÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. of the company.', '["15, paid up share capital and free reserves","15, paid up share capital, free reserves and Security Premium Account","35, paid up share capital, free reserves and Security Premium Account","35, paid up share capital and free reserves"]'::jsonb, 2, 'No company referred to in sub - section (2) of section 73 shall accept or renew any deposit from its members, if the amount of such deposits together with the amount of other deposits outstanding as on the date of acceptance or renewal of such deposits exceeds thirty five per cent of the aggregate of the Paid - up share capital, free Reserves and securities premium account of the company.'),
(19, 'No eligible company shall accept or renew deposit from non-members, if the amount of such deposit together with the amount of such other deposits, other than member deposits, outstanding on the date of acceptance or renewal exceedsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.% of aggregate of the Paid-up share capital, free Reserves and securities premium account of the company.', '["10","15","25","35"]'::jsonb, 2, 'No eligible company shall accept or renew deposit from non - members, if the amount of such deposit together with the amount of such other deposits, other than member deposits, outstanding on the date of acceptance or renewal exceeds 25% of aggregate of the Paid - up share capital, fre e Reserves and securities premium account of the company.'),
(20, 'Deposits may be accepted in joint names not exceedingÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["2","3","5","10"]'::jsonb, 1, 'Where depositors so desire, deposits may be accepted in joint names not exceeding three, with or without any of the clauses, namely, "Jointly", "Either or Survivor, "First named or Survivo r", "Anyone or Survivor".'),
(21, 'No Government shall accept or renew any deposit, if the amount of such deposits together with the amount of other deposits outstanding as on the date of acceptance or renewal exceeds Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..% of the aggregate of its Paid-up share capital, free Reserves and securities premium account of the company.', '["10","15","25","35"]'::jsonb, 3, 'No Government company eligible to accept deposits shall accept or renew any deposit. If the amount of such deposits together with the amount of other deposits outstanding as on the date of acceptance or renewal exceeds thirty five per cent. Of the aggregate of its Paid - up share capital, free Reserves and securities premium account of the company.'),
(24, 'Every company shall pay a penal rate of interest of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. p.a. for the overdue period in case of deposits, whether secured or unsecured, matured and claimed but remaining unpaid.', '["12","18","24","30"]'::jsonb, 1, 'Every company shall pa y a penal rate of Interest of 18% p.a. for the overdue period in case of deposits, whether secured or unsecured, matured and claimed but remaining unpaid.'),
(25, 'Every company accepting deposits shall on or beforeÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. of every year, file with the Registrar, a return in Form DPT-3', '["31 st May","30 th June","31 st July","31 st August"]'::jsonb, 1, 'Every company accepting deposits shall on or'),
(26, 'Section 73 prohibits a company to invite, accept or renew deposits from public. This prohibition Is applicable to :-', '["Banking company","Non- banking financial company","One person company","Company as may be specified by Central Government."]'::jsonb, 2, 'Restriction on acceptance of deposits from public shall not'),
(27, 'No eligible company shall accept or renew any deposit from its members, if the amount of such deposit together with the amount of deposits outstanding as on the date of acceptance or renewal of such deposits from members exceeds Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.% of the aggregate of the Paid-up share capital, free Reserves and securities premium account of the company.', '["10%","15%","25%","35%"]'::jsonb, 0, 'No eligible company shall accept or renew a ny deposit'),
(28, 'A company accepting deposits shall deposit such sum which shall not be less than Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. % of the amount of its deposits maturing during a financial year and the financial year next following, and keep it in a scheduled bank in a separate bank account.', '["10","15","20","25"]'::jsonb, 1, 'A company accepting deposits'),
(29, 'Acceptance of deposits from members required Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Resolution of general meeting of members.', '["General Resolution","Special Resolution","unanimous Resolution","not required any resolution of members"]'::jsonb, 1, 'Section 73(2) of the Companies Act, 2013.'),
(30, 'A sum not less than Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.of deposits maturing in current year + in next financial year shall be deposited in Ã¢â‚¬ËœDeposit Repayment Reserve AccountÃ¢â‚¬â„¢ at a scheduled bank.', '["7%","10%","15%","20%"]'::jsonb, 2, 'Section 73(2) of the Companies Act, 2013.')
) as v(question_no, question, options, correct_index, hint)
where b.title = 'CA Inter Law MCQs by Darshan Khare'
on conflict (book_id, chapter_no, question_no) do nothing;


-- ==================== CHAPTER 6 ====================

-- Chapter 6: Registration of Charges
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 6, 'Registration of Charges', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'Every company shall be duty bound to register its charges with Registrar of Companies within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Days.', '["7 days","10 days","30 days","45 days"]'::jsonb, 2, 'Section 77(1) of the Companies Act, 2013'),
(2, 'The Registrar of Companies can allow late registration beyond Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ days but within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ days from the date of its creation on payment of additional fees.', '["7 days, 100 days","10 days, 300 days","30 days, 300 days","45 days, 100 days"]'::jsonb, 2, 'Section 77(1) of the Companies Act, 2013.'),
(3, 'Where company does not registered the charge within 30 days and holder registered the same before 300 days then the limit of 300 willÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ to the company', '["Apply","Not apply","be extended","None of the above"]'::jsonb, 1, 'Section 78 of the Companies Act, 2013.'),
(4, 'Particulars of charge shall be signed by the Company and the charge holder filed together with the instrument, if any creating such charge in Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.Form', '["CHG 1","CHG 2","CHG 4","CHG 6"]'::jsonb, 0, 'Section 77(1) of the Companies Act, 2013'),
(5, 'The Registrar of Companies shall issue a certificate of registration of charge in Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..Form', '["CHG 1","CHG 2","CHG 4","CHG 6 ."]'::jsonb, 1, 'Section 77(2) of the Companies Act, 2013.'),
(6, 'Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ charge means charge which is on the specific assets of the company at the time of creation itself.', '["Fixed Charge","Floating Charge","Normal Charge","None of the above"]'::jsonb, 0, NULL),
(7, 'A charge which crystallize (becomes fixed) on occurrence of the specific event is called as Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. charge', '["Fixed Charge","Floating Charge","Normal Charge","None of the above"]'::jsonb, 1, NULL),
(8, 'Whether the assets are charged only on tangible assets. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 1, 'Section 77(1) of the Companies Act, 2013, the assets are charged on tangible assets as well as intangible assets.'),
(9, 'The provision of section 77 of the Companies Act, 2013 relating to registration of charges shall apply to-', '["a company acquiring any property subject to a charge within the meaning of that section","any modification in the terms or conditions or the extent or operation of any charge registered under that section","Both a and b","None of the above"]'::jsonb, 2, 'Section 79 of the Companies Act, 2013.'),
(10, 'A company shall give intimation of the payment or satisfaction to Registrar of Companies. Such intimation shall be sent within Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Days from the date of such payment or satisfaction.', '["7 days","10 days","30 days","45 days"]'::jsonb, 2, 'Section 82(1) of the Companies Act, 2013'),
(11, 'A company shall give intimation of the payment or satisfaction to Registrar of Companies. Such intimation shall be sent in Form NoÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["CHG 1","CHG 2","CHG 4","CHG 6"]'::jsonb, 2, 'Section 82(1) of the Companies Act, 2013.'),
(14, 'M/s XYZ Ltd. realized on 3 rd November, 2015 that particulars of a charge created on 11 th September, 2015 in favour of a Bank were not filed with the Registrar of Companies for registration. Whether company can take advantage of extended period of 300 days?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 77(1) of the Companies Act, 2013, the ROC can allow late registration beyond 30 d ays but within 300 days from the date of its creation on payment of additional fees.'),
(15, 'M/s ABC Ltd. is a public limited company, was created a charge on assets of the company on 1 st May, 2015. In how many days company shall be bound to register the particulars of its charge with Registrar of Companies?', '["7 days","10 days","30 days","45 days"]'::jsonb, 2, 'As per Section 77(1) of the Companies Act, 2013, Every company shall be duty bound to register its charges with Registrar of Companies within 30 Days.'),
(16, 'While sanctioning working limit, the rate of interest had been fixed at a specified percentage above the bank rate as notified by the Reserve bank of India. There was a change in the interest rate due to Reserve Bank of India notification issued later. The Bank insisted on filing a return of modification of charges. Is the stand of Bank correct?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Section 79 of the Companies Act, 2013, the term Ã¢â‚¬ËœmodificationÃ¢â‚¬â„¢ includes variation of any of the terms of the agreement including variation of rate of interest which may be by mutual agreement or by operation of law.'),
(17, 'Under section 77(1) of the Companies Act, 2013 it shall be the duty of every company creating a chargeÃ¢â‚¬Â¦', '["within or outside India","on its property or assets or any of its undertakings","Situated in or outside India","All of the above"]'::jsonb, 3, 'Section 77(1) of the Companies Act, 2013.'),
(18, 'M/s ABC Ltd. is a public limited company, was made a payment or satisfaction of charge on assets of the company which was created in 2005. In how many days company shall give intimation of the payment or satisfaction to the Registrar of Companies?', '["7 days","10 days","30 days","45 days"]'::jsonb, 2, 'Section 82 of the Compani es Act, 2013.'),
(19, 'Where the satisfaction of the charge is not filed within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..days from the date on which such payment of satisfaction, the Registrar shall not register the same unless the delay is condoned by the Central Government.', '["14","30","60","300"]'::jsonb, 1, NULL),
(20, 'Where a company fails to register the charge within the period 30 days, the person in whose favour the charge is created may apply to the Registrar for registration of the charge within a period of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.days after giving notice to the company,', '["14","30","60","300"]'::jsonb, 0, 'As per section 78 of the Companies Act, 2013, where a company falls to register the charge within the period 30 days, the person in whose favour the charge is created may ap ply to the Registrar for registration of the charge along with the instrument created for the charge, within such time and in such form and manner as may be prescribed and the Registrar may, on such application, within a period of 14 days after giving noti ce to the company'),
(21, 'The register of charges and instrument of charges shall be open for inspection during:', '["Working Hours","Business hours","At all times","9 a.m. to 5 p.m."]'::jsonb, 1, 'The register of charges maintained by company shall be opened for Inspection during business hours only.'),
(22, 'The register of charges shall be preserved forÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦years.', '["7","8","10","Permanently"]'::jsonb, 3, 'The register of charges shall be preserved for permanently.'),
(23, 'Instrument of charge shall be preserved for a time period of from the date of satisfaction of charge:', '["5 years","7 years","8 years","15 years"]'::jsonb, 2, 'The time limit for preservation of instrument of charge after its satisfaction Is 8 years.'),
(26, 'Satisfaction of charge shall be record by', '["Company","Charge holder","Registrar","All of the above"]'::jsonb, 3, 'Charge shall be satisfied by company, registrar charge holder.'),
(27, 'A person acquiring property shall be deemed to have notice of charge fromÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["End of 30 days","Date of application from charge","Date acquiring the property","Date of such registration"]'::jsonb, 3, 'Charge created on property or asset of a company is considered to be notice to worldwide at Large and any person dealing in It shall be deemed to have intimation of it from that date.'),
(28, 'Charge shall be register if not register in 30 days', '["300 days of its creation","300 days after completion of 30 days","Anytime since satisfaction","Suo moto power of company"]'::jsonb, 0, 'Registration may be allow the registration of charge after 30 days of Its creation, but within 300 days of creation of creation of charge.'),
(29, 'By whom the charge should be created?', '["Company","Lender","Borrower","Charge holder"]'::jsonb, 0, 'According to companies act, it is the duty of company to register the charge created on It.'),
(30, 'Which of these charge is an identifiable charge?', '["Floating charge","Fixed charge","Hypothecation","Both a and b"]'::jsonb, 1, 'Fixed charge is that type of charge which is created on specific asset and Is easily Identifiable'),
(31, 'Charge shall be registered byÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["company","charge holder","Registrar","Both a and b"]'::jsonb, 3, 'Charge may be registered by Company and Charge holder himself if Company is unable to register it.'),
(32, 'A company shall give Intimation to the Registrar of the payment or satisfaction in full of any charge within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..days from the date of such payment or satisfaction.', '["14","30","60","300"]'::jsonb, 1, 'According to section 82 of the C ompanies Act, 2013, a company shall give Intimation to the Registrar In the prescribed form (Form CHG 1), of the payment or satisfaction In full of any charge registered under this'),
(39, 'The instrument creating a charge or modification thereon shall be preserved forÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. years from the date of satisfaction of charge by the company.', '["7","8","10","Permanently"]'::jsonb, 1, 'The instrument creating a charge or modification thereon shall be preserved for a period of 8 years from the date of satisfaction of charge by the company.'),
(40, 'If condonation of delay of beyond 300 days then company shall make application to', '["Tribunal","CG","Registrar","Charge older"]'::jsonb, 1, 'Company shall make an application to CG.'),
(41, 'If any company contravenes any provision relating to the registration of charges, every officer of the company who is in default shall be punishable with imprisonment for a term which may extend toÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ or with fine which shall not be less than RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ but which may extend to RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦..', '["One year, 3, 50000, 300000","Six months, 25000, 200000","Three years, 100000, 200000","Six months, 25000, 100000"]'::jsonb, 3, 'According to section 86 of the Companies Act, 2013, If any company contravenes any provision relating to the registration of charges contained under chapter VI of the Act, every officer of the company who is in default shall be punishable with imprisonment for a term which may extend to six months or with fine which shall not be less than twenty - five thousand rupees but which may exten d to one lakh rupees, or with both.'),
(24, 'Charge shall be registered with the registrar within', '["300 days of its creation","30 days of its creation","30 days of satisfaction of charge","300 days of satisfaction of charge"]'::jsonb, 0, 'For registration of charge of debenture in Form CHG 9 is used.'),
(43, 'Register of charges can be inspected by anyone of free of cost.', '["True","False","Partly True","Partly False"]'::jsonb, 1, 'The register of charges and instrument of charges, shall be open for Inspection during business hours Ã¢â‚¬â€ (a) By any member or creditor without any payment of fees; or (b) By any other person on payment of such fees as may be prescribed, -subject to such reasonable restrictions as the company may, by Its articles, Impose'),
(44, 'Form used for registration of charge other than debentures is:', '["Form CHG-9","Form CHG-2","Form CHG-5","Form CHG-1"]'::jsonb, 3, 'The form CHG - 1 is used for application for registration of charge other than debentures.'),
(45, 'What is the additional time limit for registration of charge from the date of end of basic time limit?', '["270 days","300 days","45 days","365 days"]'::jsonb, 0, 'The additional time limit for registration of charge Is 270 days if charge is not registered within 30 days of its creation.'),
(46, 'What is the basic time limit for registration of charge created on a company?', '["270 days","300 days","45 days","30 days"]'::jsonb, 3, 'The section 77 of companies act, 2013 states that the company should register c harge within 30 days of its creation.'),
(47, 'It shall be duty of the company creating a charge within or outside India, to register the particulars of the charge signed by the company and the charge holder together with the instruments, with the register withinÃ¢â‚¬Â¦Ã¢â‚¬Â¦. Days of creation.', '["14","30","60","300"]'::jsonb, 1, 'It shall be duty of the company creating a charge within or outside India, on its property or assets or any of its undertaking, whether tangible or otherwise and situated in or outside India, to register the particulars of the charge signed by the company and the charge holder together with the instruments, if any, creating such charge in such form, on payment of such fees and in such manner as may be prescribed, with the registrar within 30 days of creation.'),
(48, 'Time limit for registration of charge by charge holder if charge not registered within 30 days off its creation is:', '["14 days","21 days","30 days","60 days"]'::jsonb, 0, 'Sec 77 of companies act, 2013 states that If the company doesn''t register charge within 30 days of its creation, then the charge holder can file an application to ROC within 14 days for registration of its charge.'),
(49, 'Form CHG-2 is for:', '["Certificate of registration of charge","Registration of charge","Modification of charge","Debenture"]'::jsonb, 0, 'Form CHG - 2 is used for Certificate of registration of charge given by'),
(50, 'The particulars of charges maintained by MCA at which portal?', '["www.gst.gov.in","www.indiangv.in","www.mca.gov.in/MCA21","Both a and b"]'::jsonb, 2, 'The register of charges are maintained by ROC at www.mca.gov.in/MCA21 website.'),
(51, 'Crystallization is possible in which of these charges?', '["Fixed charge","Floating charge","Hypothecation","Pledge"]'::jsonb, 1, 'Crystallization means conversion of floating charge into fixed charge which is on ly possible in floating'),
(52, 'Which of the following is not possible in case of modification?', '["Change in terms and conditions","Satisfaction of charge","Pair Paso change","Change In agreement."]'::jsonb, 1, 'Modification canÃ¢â‚¬â„¢t be done in case of satisfaction of charge.'),
(53, 'What is the time limit for preservation of register of charges?', '["8 years","Permanently","15 years","21 years"]'::jsonb, 1, 'The register of charges maintained by company should be preserved permanently whereas instrument relating to it for 8 years.'),
(54, 'ROC should not give show cause notice to charge holder for satisfaction of charge if it is signed by:', '["Charge holder","Company Secretary","Board of directors","Any one of the above."]'::jsonb, 0, 'If the satisfaction form is being signed by the charge holder, then no show cause notice Is given to ROC for such intimation.'),
(55, 'Which of the following conversion is possible?', '["Fixed charge into Floating charge","Floating charge into Fixed charge","Both of the above","No conversion is possible"]'::jsonb, 1, 'Floating charge can be converted into Fixed charge but vice versa is not possible.'),
(57, 'Every company shall keep at its registered office a register of charges in formÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["CHG-9","CHG-2","CHG-5","CHG-7"]'::jsonb, 3, NULL),
(58, 'Expenses occurred by charge holder for registration of charge would be reimbursed from:', '["Own","Company","Both company and charge holder equally","Mutual understanding of company and charge holder"]'::jsonb, 1, 'Expenses incurred by charge holder for registration of charge would be reimbursed from the company.'),
(59, 'Entries in the register of companies shall be done by:', '["Director","Company Secretary","Person authorized by Board","Any one of the above"]'::jsonb, 3, 'The entries in register of charges of company shall be done by the director of the company or secretary of the company or any other person which is authorized by board to do so.')
) as v(question_no, question, options, correct_index, hint)
where b.title = 'CA Inter Law MCQs by Darshan Khare'
on conflict (book_id, chapter_no, question_no) do nothing;


-- ==================== CHAPTER 7 ====================

-- Chapter 7: Management and Administration of Companies
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 7, 'Management and Administration of Companies', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'Which types of registers shall be maintained by company?', '["Register of members","Register of debenture holders","Register of other security holders","All of the above"]'::jsonb, 3, 'As per section 88(1) of the Companies Act, 2013, all the aforesaid registers shall be maintained in a manner and format as may be prescribed.'),
(2, 'Which register shall be compulsorily maintained by company?', '["Register of members","Register of debenture holders","Register of other security holders","All of the above"]'::jsonb, 0, 'Section 88 of the Companies Act, 2013'),
(3, 'Total days of one time closure of register of members or debenture holders or other security holders shall not exceedÃ¢â‚¬Â¦Ã¢â‚¬Â¦. Days.', '["10 days","20 days","30 days","45 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013, maximum period of closure.'),
(4, 'Total closure days in year together of all closure of register of members or debenture holders or other security holders shall not exceedÃ¢â‚¬Â¦Ã¢â‚¬Â¦. Days.', '["30 days","40 days","45 days","60 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013, maximum period of closure.'),
(5, 'Notice regarding closure of books and registers of members or debenture holders or other security holders to SEBI & ROC at least Ã¢â‚¬Â¦.. Days before the first day of closure.', '["1 day","5 days","7 days","10 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013, maximum period of closure.'),
(6, 'State the penalty for every day during which the register is kept closed in contravention of Section 91 of the Companies Act, 2013, for Compan y and every officer in defaultÃ¢â‚¬Â¦', '["Rs. 5,000 per day of default or Rs. 100000, whichever is lower","Rs. 5,000 per day of default or Rs. 100000, whichever is Higher","Rs. 10,000 per day of default or Rs. 100000, whichever is Higher","Rs. 10,000 per day of default or Rs. 100000, whichever is lower"]'::jsonb, 0, 'Section 91(2) of the Companies Act, 2013.'),
(7, 'ABC Ltd. is a public limited company desires to declare dividend. For that company will need to close registers of members or debenture holders or other security holders. In how many days company should inform about closure of registers to SEBI & ROC?', '["1 day","5 days","7 days","10 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013.'),
(8, 'Can annual general meeting be held on a national holiday?', '["Yes","No","Specific Cases","After approval of shareholders"]'::jsonb, 1, 'Under section 96(2) of the Companies Act, 2013 every annual general meeting shall be called during nosiness hours i.e. between 9 a.m. to 6 p.m. on any day that is not a national holiday'),
(9, 'First Annual General meeting shall be within period of Ã¢â‚¬Â¦Ã¢â‚¬Â¦ months from the date of closing of the first financial year of the company.', '["3 months","6 months","9 months","15 months Section 96(1) of the Companies Act, 2013, time limit to hold AGM."]'::jsonb, 2, 'Section 96(1) of the Compa nies Act, 2013, time limit to hold AGM'),
(12, 'The Financial year of ABC Ltd. ended on 31 st March, 2018, The Annual General meeting of the company was held on 10 th October, 2018. As per requirement of the Companies Act, 2013, the Annual Return of the company should be filed with Registrar of Companies within Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["60 days from 10 th October, 2018","60 days from 30 th September, 2018","90 days from 30 th September, 2018","90 days from 10 th October, 2018"]'::jsonb, 1, 'As per Section 92(4) of the Companies act, 2013, every Company shall file with the Registrar a copy of the Annual Return, within 60 days from the date on which the annual general meeting is held or where no annual general meeting is held in any year within 60 days from the date on which annual general meeting should have been held together with the statement specifying the reasons for not holding annual general meeting, with such fees or additional fees as may be prescribed.'),
(13, 'The gap between two Annual General Meeting must not be more than', '["12 months as may be extended by Registrar of Companies to 18 months","15 months as may be extended by Registrar of Companies to 20 months","18 months as may be extended by Registrar of Companies to 20 months","15 months as may be extended by Registrar of Companies to 18 months"]'::jsonb, 3, 'As per Section 96(1) of the Companies Act, 2013, not more than 15 months shall elapse between the date of one Annual General Meeting and that of the next. However, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(14, 'The Financial year of ABC Ltd. ended on 31 st March, 2020, due to some specific reason, the company will not be eligible to conduct the Annual General meeting of the company at or before 30 th September, 2020. Whether Company can apply to the Registrar of Companies for extension of time for the Annual General meeting?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 96(1) of the Companies Act, 2013, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(15, 'An extra ordinary general meeting may be convened byÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Board of Directors","Requistionists","Company Law Board/Tribunal","All of the above"]'::jsonb, 3, 'Section 98 & 100 of the Companie s Act, 2013.'),
(16, 'The time period for conduction of AGM is extended by ROC for how many months?', '["1 month","2 months","4 months","3 months"]'::jsonb, 3, 'As per Section 96(1) of the Companies Act, 2013, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(17, 'M/s Infotech Ltd. was incorporated on 1 st April, 2015. No general meeting of the company has been held within a period of 9 months from the date of closing of the first financial year of the company. Whether registrar can grant extension of time for the first Annual General Meeting?', '["Yes","No","Exceptional cases","None of the above"]'::jsonb, 1, 'As per Section 96(1) of the Companies Act, 2013, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(18, 'Resolution requiring special notice is requiredÃ¢â‚¬Â¦Ã¢â‚¬Â¦', '["For appointment of a person other than the retiring auditor as auditor at the Annual General Meeting","For removing a director before the expiry of the period of his office","Both a and b","None of the abo ve"]'::jsonb, 2, 'Section 169(2) & 140(4) of the Companies Act, 2013.'),
(22, 'Every listed company shall file a return specifying the change in the number of shares held by promoters and top 10 shareholders and such return shall be filed with ROC within Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Days of such change.', '["7 days","10 days","15 days","30 days"]'::jsonb, 2, 'Section 93 of the Compani es Act, 2013.'),
(23, 'The registers and indexes and copies of annual return shall be kept atÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["The registered office of the company","Any other place in India if more than 10% of the total number of members reside at such place","Both a and b","None of the above"]'::jsonb, 2, 'Section 94(1) of the Companies Act, 2013, any other place in India if more than 10% of the total number of members reside at such place(GM-SR required and ROC has been given in advance a copy of the proposed SR'),
(24, 'All the records(only public documents) shall be open for inspection by', '["Any member or debenture holders","other security holders or beneficial owner","Any other person","All of the above"]'::jsonb, 3, 'Section 94(2) of the Companies Act, 2013, all the records (only public documents) shall be open for inspection by Any member or debenture holders or other security holders or beneficial owner without fees and Any other person with fees.'),
(25, 'If the company refuses to allow any inspection or taking of any extract, penalty for the company and every officer in default shall be', '["Rs. 1,000 per day of defaulting period or Rs. 1,00,000 whichever is lower","Rs. 1,000 per day of defaulting period or Rs. 1,00,000 whichever is higher","Rs. 2,000 per day of defaulting period or Rs. 1,00,000 whichever is higher","Rs. 2,000 per day of defaulting period or Rs. 2,00,000 whichever is lower"]'::jsonb, 0, 'Section 94(4) of the Companie s Act, 2013'),
(26, 'Mr. Ram is a shareholder of M/s ABC Ltd. desires to inspect the registers of the company. Whether he can do so?', '["Yes","No","Approval BOD","Approval other shareholders"]'::jsonb, 0, 'Section 94(2) of the Companies Act, 2013, all the records (only public documents) shall be open for inspection by Any member or debenture holders or other security holders or beneficial owner without fees and Any other person with fees.'),
(28, 'M/s XYZ Pvt. Ltd, is a Private limited company, incorporated at 30 th September, 2018. State the date of First Annual General meeting.', '["30.09.2019","31.12.2019","30.09.2020","31.12.2020"]'::jsonb, 1, 'The First Annual General Meeting of the company shall be held within 9 months from the end of first financial year. The First Financial year of M/s XYZ Pvt. Ltd. ended on 31 st March, 2019. (Section 96(1) of the Companies Act, 2013)'),
(29, 'M/s XYZ Ltd, is a public limited company, incorporated at 1 st January, 2019. State the date of First Annual General meeting.', '["30.09.2020","31.12.2020","30.09.2021","31.12.2021"]'::jsonb, 1, 'The First Annual General Meeting of the company shall be held within 9 months from the end of first financial year. The First Financial year of M/s XYZ Ltd. ended on 31 st March, 2020. (Section 96(1) of the Companies Act, 2013)'),
(30, 'M/s ABC Pvt. Ltd, is a Private limited company, incorporated at 31 st March, 2019. State the date of First Annual General meeting.', '["30.09.2020","31.12.2020","30.09.2021","31.12.2021"]'::jsonb, 1, 'The First Annual General Meeting of the company shall be held within 9 months from the end of first financial year. The First Financial year of M/s ABC Pvt. Ltd. ended on 31 st March, 2020. (Section 96(1) of the Companies Act, 2013)'),
(31, 'If any default is made in holding the Annual General meeting under section 96 of the Companies Act, 2013, an application to call or direct calling of meeting is made to the Ã¢â‚¬Â¦. By any member.', '["High Court","SEBI","NCLT","None of the above"]'::jsonb, 2, 'Section 97(1) of the Companies Act, 2013, Power of Tribunal to call or direct calling of meeting.'),
(32, 'If any default is made in holding the Annual General meeting under section 96 of the Companies Act, 2013, an application to call or direct calling of meeting is made to the Tribunal by Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["Promoters","Board of directors","Any shareholders","None of the above"]'::jsonb, 2, 'Section 97(1) of the Companies Act, 2013, Power of Tribunal to call or direct calling of meeting.'),
(33, 'When for any reason it is impractical to call a meeting other than an annual general meeting of a company, an application is made by any director or member who would be entitled to vote at such meeting. The Tribunal may, sou motu be of opinion to order such meeting of members. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'Section 98(1) of the Companies Act, 2013, Power of Tribunal to call meeting of members.'),
(34, 'If any default is made in holding a meeting of a company as per Section 96, 97 or 98 of the Companies Act, 2013 or complying with any directions of the Tribunal, penalty for the company and every officer in default..', '["For one time default Ã¢â‚¬â€œ Fine up to Rs. 1,00,000 For Continuing Default Ã¢â‚¬â€œ Fine up to Rs. 5,000 per day for the defaulting period","For one time default Ã¢â‚¬â€œ Fine up to Rs. 2,00,000 For Continuing Default Ã¢â‚¬â€œ Fine up to Rs. 5,000 per day for the defaulting period","For one time default Ã¢â‚¬â€œ Fine up to Rs. 1,00,000 For Continuing Default Ã¢â‚¬â€œ Fine up to Rs. 1,000 per day for the defaulting period","For one time default Ã¢â‚¬â€œ Fine up to Rs. 2,00,000 For Continuing Default Ã¢â‚¬â€œ Fine up to Rs. 2,000 per day for the defaulting period"]'::jsonb, 0, 'Section 99 of the Companies Act, 2013, punishment for default in complying with provision of Section 96 to Section 98 of the Companies Act, 2013'),
(35, 'Who can make a valid requisition in case of company having a share capital?', '["Members holding 5% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition","Member holding 10% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition","Member holding 20% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition","Member holding 51% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition"]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013'),
(36, 'Who can make a valid requisition in case of company not having a share capital?', '["Members having 5% or more of the total voting power of all the members as at the date of deposit of the requisition.","Members having 10% or more of the total voting power of all the members as at the date of deposit of the requisition.","Members having 20% or more of the total voting power of all the members as at the date of deposit of the requisition.","Members having 51% or more of the total voting power of all the members as at the date of deposit of the requisition."]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013'),
(37, 'The Board of Directors shall call an Extra Ordinary general meeting on receiving valid requisition from members on a day not later thanÃ¢â‚¬Â¦Ã¢â‚¬Â¦ days from the date of receipt of such requisition.', '["30 days","45 days","60 days","90 days"]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013, Board of Directors legally bound to call Extra Ordinary general meeting on receiving valid requisition from members.'),
(38, 'The Board of Directors shall within Ã¢â‚¬Â¦. Days from the date of receipt of valid requisition from members, proceed to call an Extra Ordinary general meeting.', '["15 days","21 days","45 days","30 days"]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013, Board of Directors legally bound to call Extra Ordinary general meeting on receiving valid requisition from members.'),
(39, 'If board fails to call the Extra Ordinary general meeting on receiving valid requisition from members, the meeting may be called and held by requisitonists themselves within a period of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Months from the date of the requisition.', '["1 Month","2 Months","3 Months","6 Months"]'::jsonb, 2, 'Section 100(4) of the Companies Act, 2013'),
(40, 'Which are the items of business that require special notice?', '["Ã¢â‚¬â€œ Resolution at AGM appointing as auditor a person other than retiring auditor. - Resolution at AGM providing expressly that retiring auditor shall not be reappointed","Ã¢â‚¬â€œ Resolution for removal of a director. - Resolution to appoint somebody in place of a director removed at the meeting at which he is removed","Both a and b","None of the above"]'::jsonb, 2, 'Section 115 of the companies Act, 2013, resolutions required special notice.'),
(41, 'The special notice is given by members holding not less than Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ total voting power or holding shares on which such aggregate sum not exceeding Ã¢â‚¬Â¦Ã¢â‚¬Â¦ rupees, as may be prescribed has been paid up.', '["1%, Rs. 5 Lakh","10%, Rs. 5 Lakh","1%, Rs. 10 Lakh","10%, Rs. 10 Lakh"]'::jsonb, 0, 'Section 115 of the companies Act, 2013, resolutions required special notice.'),
(42, 'Mr. Ram is a shareholder of the M/s ABC Ltd. Company , having 2% voting power, desires to call an Extra Ordinary general meeting. Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'Removal of director is a one of the business which requires special notice. The special notice is given by members holding not less than 1% total voting power or holding shares on which such aggregate sum not exceeding 5 lakhs'),
(43, 'Mr. Shyam is a shareholder of the M/s ABC Ltd. Company , having less than 1% voting power, desires to call an Extra Ordinary general meeting for appointment as auditor a person other than retiring auditor. Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 1, 'Appointment as auditor a person other than retiring auditor is a one of the business which requires special notice. The special notice is given by members holding not less than 1% total voting power or holding shares on which such aggregate sum not exceeding 5 lakhs rupees,'),
(44, 'Mr. Shyam is a shareholder of the M/s ABC Ltd. Company , holding shares of aggregate sum is Rs. 5 lakhs, desires to call an Extra Ordinary general meeting for removal of director. Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'Removal of director is a one of the business which requires special notice. The special notice is given by members holding not less than 1% total voting power or holding shares on which such aggregate sum not exceeding 5 lakhs rupees, as may be'),
(45, 'Mr. Ram is a shareholder of the M/s ABC Ltd. ( Company not having a share capital ) , having 10% voting power, desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'As per Section 100 of the Companies Act, 2013, In case of Company not having a share capital, members having 10% voting power of all the members as at the date of deposit of the re quisition have right to make requisition.'),
(46, 'Mr. Shyam is a shareholder of the M/s ABC Ltd. ( Company having a share capital ) , holding 10% of the paid up share capital of the company having right to vote , desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'As per Section 100 of the Companies Act, 2013, In case of Company having a share capital, members holding 10% of the paid up share capital of the company having right to vote as at the date of deposit of the requisition have right to make requisition.'),
(47, 'Mr. Rajesh is a shareholder of the M/s ABC Ltd. (Company having a share capital), holding 1% of the paid up share capital of the company having right to vote, desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 1, 'As per Section 100 of the Companies Act, 2013, In case of Company having a share capital, members holding 10% of the paid up share capital of the company having right to vote as at the date of deposit of the requisition have right to make requisition'),
(48, 'Mr. Kiran is a shareholder of the M/s ABC Ltd. (Company not having a share capital), having 1% voting power, desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 1, 'As per Section 100 of the Companies Act, 2013, In case of Company not having a share capital, members having 10% voting power of all the members as at the date of deposit of the requisition have right to make requisition.'),
(51, 'The Board of Director of a company refuse to convene the Extra Ordinary general meeting of the members on the ground that the reqisitionists have not been signed by the joint holder of the shares. (Power of attorney is assumed one) Whether Board of Director can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Where 2 or more persons hold any shares or interest in a company jointly, a requisition or notice calling a meeting, signed by one or some of them shall, for the purpose of Section 100 of the Companies Act, 2013, have same force and effect as if it had been signed by all of them.'),
(52, 'M/s XYZ Ltd. called its Annual General Meeting on 28 th September, 2018. The notice of the meeting was posted on 6 th September, 2018. With reference to the provision of the Companies Act, 2013 examine whether the notice given by the company was valid?', '["Valid","Invalid","Valid after approval Board","canÃ¢â‚¬â„¢t say"]'::jsonb, 1, 'As per Section 101 of the Companies Act, 2013, 21 clear daysÃ¢â‚¬â„¢ notice has not been served.'),
(53, 'Who are the persons entitled to receive notice of a general meeting of a company, registered under the Companies Act, 2013?', '["To every member of the company, legal representative of any deceased member, or the assignee of an insolvent member","To every director of the company","To an auditor or auditors","All of the above"]'::jsonb, 3, 'Section 101 of the Companies Act, 2013'),
(54, 'Accidental Non receipt of notice of the general meeting by any member invalidate the proceeding of the meeting?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Accidental Non receipt of notice of the general meeting by any member shall not invalidate the proceeding of the meeting(Section 101 of the Companies Act, 2013'),
(56, 'Every notice shall specifyÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Date and day of the meeting","Place and hour of the meeting","Business to be transacted","All of the above"]'::jsonb, 3, 'Section 101 of the Compani es Act, 2013.'),
(57, 'Any General Meeting can be called by giving at least Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Clear daysÃ¢â‚¬â„¢ notice .', '["7 days","14 days","21 days","30 days"]'::jsonb, 3, 'Section 101 of the Companies Act, 2013.'),
(58, 'Mr. Rajesh, secretary of ABC Ltd. called an Extra Ordinary general meeting of the company on the requisition of some members. Mr. Rajesh, secretary of the company issued notice of the meeting without the authority of the Board of Directors. Whether he can do so?', '["Yes","No","in specific cases, it is allowed","canÃ¢â‚¬â„¢t say"]'::jsonb, 2, 'Section 101 of the Companies Act, 2013.'),
(59, 'Mr. Rajesh, secretary of ABC Ltd. called an Extra Ordinary general meeting of the company on the requisition of some members. Mr. Rajesh, secretary of the company issued notice of the meeting without the authority of the Board of Directors. Mr. Rajesh, secretary of the company is already specially authorized by Board of Directors and AOA of the company for the same. Whether he can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 101 and 115 of the Companies Act, 2013.'),
(60, 'Explanatory statement must be annexed to the notice for transacting every item of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Business.', '["Ordinary","Special","All of the above","None of the above"]'::jsonb, 0, 'Section 101 and 115 of the Companies Act, 2013.'),
(61, 'Contents of Explanatory statementÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["the nature of concern or interest , financial or otherwise, in respect of each items of every director and manager and their relatives","the nature of concern or interest , financial or otherwise, in respect of each items of every other key managerial personnel and their relatives","any other information and facts that may enable members to understand the meaning, scope and implications of the items of business","All of the ab ov e"]'::jsonb, 1, 'Section 102(1) of the Companies Act, 2013'),
(62, 'All business to be transacted at Annual General Meeting shall be deemed special exceptÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["the consideration of financial statement and the reports of the Board of directors and auditors","Declaration of dividend","the appointment of director in place of those retiring and the appointment of , and the fixing of the remuneration of, the auditors","All of th e ab ov e"]'::jsonb, 3, 'Section 102(1) of the Companies Act, 2013'),
(63, 'Which one of the following required ordinary resolution?', '["To change the name of the company","To alter the article of association","To reduce share capital","to declare dividend"]'::jsonb, 3, 'Section 102(2) of the Companies Act, 2013'),
(64, 'Which one of the followin g required ordinary resolution?', '["the consideration of financial statement and the reports of the Board of directors and auditors","To increase share capital","To alter the Memorandum of association","To alter the article of association"]'::jsonb, 3, 'Section 102(2) of the Companies Act, 2013'),
(65, 'Which one of the followin g required ordinary resolution?', '["To change the registered office of the company","the appointment of director in place of those retiring and the appointment of , and the fixing of the remuneration of, the auditors","To reduce share capital","To alter the Memorandu m of association"]'::jsonb, 0, 'Section 102(2) of the Companies Act, 2013'),
(66, 'Penalty for contravention of Section 102(5) of the Companies Act, 2013. ( Explanatory statement)', '["Higher of - Fine up to Rs. 50,000 or - 5 * amount of benefit to person liable","Lower of - Fine up to Rs. 50,000 or - 5 * amount of benefit to person liable","Higher of - Fine up to Rs. 1,00,000 or - 5 * amount of benefit to person liable","Lower of - Fine up to Rs. 1,00,000 or - 5 * amount of benefit to person liable"]'::jsonb, 1, 'Section 102(2) of the Companies Act, 2013'),
(67, 'Quorum requirement for general meeting in case of a Public CompanyÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["Ã¢â‚¬â€œ 5 members personally present if members>1000 - 15 members personally","Ã¢â‚¬â€œ 2 members personally present if members>1000 - 10 members personally","Ã¢â‚¬â€œ 5 members personally present if members>1000 - 20 members personally","Ã¢â‚¬â€œ 2 members personally present if members>1000 - 15 members present if 1000 < members<5000 - 30 members personally present if members>5000 present if 1000 < members<5000 - 30 members personally present if members>5000 present if 1000 < members<5000 - 50 members personally present if members>5000 personally present if 1000 < members<5000 - 50 members personally present if members>5000"]'::jsonb, 0, 'Section 102(5) of the Companies Act, 2013'),
(68, 'Quorum requirement for general meeting in case of a Private CompanyÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦', '["2 members personally present","As per AOA","2 members personally present or the numbers prescribed by article whichever is higher","None of the above"]'::jsonb, 0, 'Section 103(1) of the Companies Act, 2013'),
(69, 'If the quorum is not presented within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ from the time appointed for holding a meeting of the company, the meeting shall stand adjourned.', '["15 minutes","Half an hour","One hour","Two hour"]'::jsonb, 2, 'Section 103(1) of'),
(70, 'If the quorum is not presented within half an hour from the time appointed for holding a meeting of the company, the meeting shall stand adjourned to Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["to the same day in the next week at the same time and place","to such other date and such other time and place as the Board may determine or as per AOA","the meeting if called by requisitionists shall stand cancelled","All of the above"]'::jsonb, 1, 'Section'),
(71, 'If the quorum is not present within half an hour from the time appointed for holding adjourned meeting then', '["Meeting shall stand terminated","Present member will be considered as quorum","Meeting will adjourned again","None of the above"]'::jsonb, 3, 'Section 103(2'),
(72, 'A general meeting of a Public Company was adjourned by the chairman for want of quorum. The meeting shall stand adjourned to the same day in next week, at the same time and place. In adjourned meeting also, quorum is not present within half an hour from the time appointed for holding meeting, thenÃ¢â‚¬Â¦Ã¢â‚¬Â¦.', '["Meeting shall stand terminated","Present member will be considered as quorum","Meeting will adjourned again","None of the above"]'::jsonb, 1, 'Section'),
(73, 'A person representing three member companies can be counted for the purpose of quorum in a general meeting of a Public Company.', '["Yes, A person representing three member companies will be counted as 1 for only one member in the computation of the quorum","Yes, A person representing three member companies will be counted as 2 for two member in the computation of the quorum","Yes, A person representing three member companies will be counted as 3 in the computation of the quorum","No, A person representing three member companies will not be counted."]'::jsonb, 1, 'Section 103(3) of the Companies Act, 2013'),
(74, 'Both the joint owners of shares present at the meeting can be counted as two shareholders for the purpose of quorum in a general meeting of a Public Company. True or False.', '["True","False","Partly True, counted as two but not for quorum","no provision regarding it"]'::jsonb, 2, 'Section 103 of the Companies Act, 2013'),
(75, 'A single member present at the meeting can be counted for the purpose of quorum in a general meeting of a Public Company.', '["Yes","No","Required joint shareholders only","Counted In specific meetings only"]'::jsonb, 1, 'For the purpose of quorum in a general meeting of a Public Company, joint shareholders will be collectively regarded as one shareholder. ( Section 103 of the Companies Act, 2013)'),
(78, 'The Annual General Meeting of XYZ Ltd. was held on 30 th April, 2015. The Article of Association of the company is silent regarding the quorum of the General meeting. Only 25 members were personally present in the above meeting out of 7000 members within half an hour. Whether Chairman can adjourn the meeting.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 103 of the Companies Act, 2013, quorum is required in case of Public Company Ã¢â‚¬â€œ Ã¢â‚¬â€œ 5 members personally present if members>1000 - 15 members personally present if 1000 < members<5000 - 30 members personally present if members>5000'),
(79, 'The Annual General Meeting of XYZ Pvt. Ltd. was held on 30 th April, 2015. The Article of Association of the company is silent regarding the quorum of the General meeting. Only 2 members were personally present in the above meeting out of 180 members within half an hour. Whether Chairman can adjourn the meeting.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 103 of the Companies Act, 2013, quorum is required in case of Public Company Ã¢â‚¬â€œ Ã¢â‚¬â€œ 5 members personally present if members>1000 - 15 members personally present if 1000 < members<5000 - 30 members personally present if members>5000'),
(80, 'State the rights of Proxy.', '["Right to attend the meeting and right to vote on poll","Right to act on behalf of the appointing member","Right to demand a poll if eligible u/s 109 of the Companies Act, 2013","All of the above"]'::jsonb, 0, 'As per Section 103 of the Companies Act, 2013, Quorum requirement for general meeting in case of a Private Company is 2.'),
(81, 'State the restrictions on Proxies.', '["Not have right to speak in the meeting","cannot vote on show of hands","not counted for the purpose of quorum","All of the above"]'::jsonb, 3, 'Section 105(1) of the Companies Act, 2013'),
(82, 'The Proxy Form shall be in writing and signed by the member/Attorney. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 3, 'Section 105(1) of the Companies Act, 2013'),
(83, 'Every member entitled to vote at a meeting or on any resolution to be moved thereat shall be entitled to inspect proxies lodged during the period beginning Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. Hours before the time fixed for commencement of meeting and ending with the conclusion of the meeting at any time during the business hours of the Company.', '["12 Hours","24 Hours","48 Hours","60 Hours"]'::jsonb, 0, 'Section 105(6) of the Companies Act, 2013'),
(84, 'Every member entitled to vote at a meeting or on any resolution to be moved thereat shall be entitled to inspect proxies lodged during the period beginning 24 Hours before the time fixed for commencement of meeting and ending with the conclusion of the meeting at any time during the business hours of the Company. Provided Ã¢â‚¬Â¦Ã¢â‚¬Â¦. DaysÃ¢â‚¬â„¢ notice in writing of intension to inspect is given to the company.', '["1 day","2 days","3 days","7 days"]'::jsonb, 1, 'Section 105(8) of the Companies Act, 2013'),
(85, 'Mr. Ram, a shareholder of the company, after appointing Mr. Shyam as his proxy at meeting of the company, himself attended the meeting and voted on a particular resolution. Shyam thereafter claimed to exercise his vote. Whether he can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 2, 'Section 105(8) of the Compa nies Act, 2013'),
(88, 'K, a shareholder of XYZ ltd. appoints L as his proxy to attend the general meeting of the company. Later K also attends the meeting. Both K and L voted on a particular resolution in the meeting. KÃ¢â‚¬â„¢s vote was declared invalid by the chairman stating that since he has appointed the proxy and LÃ¢â‚¬â„¢s vote has been considered as valid. Whether K can raise objection to the decision of the Chairman?', '["Yes","No","raise objection but with the approval of other members","raise objection but with the approval of BOD"]'::jsonb, 1, 'Section 105(8) of the Companies Act, 2013, Every member entitled to vote at a meeting or on any resolution to be moved thereat shall be entitled to inspect proxies lodged during the period beginning 24 Hours before the time fixed for commencement of meeting and ending with the conclusion of the meeting at any time during the business hours of the Company. Provided 3 DaysÃ¢â‚¬â„¢ notice in writing of intension to inspect is given to the company.'),
(89, 'A proxy has no right to speak at the general meeting of a company. True or False.', '["True","False","Partly True","Partly False, with permission of Chairman"]'::jsonb, 0, 'Where a shareholder who having appointed a proxy, personally attends and votes at the meeting, the proxy is revoked thereby. (Section 105 of the Companies Act, 2013)'),
(90, 'A proxy cannot vote on show of hands at the general meeting of a company. True or False.', '["True","False","Partly True","Partly False, with permission of Chairman"]'::jsonb, 0, 'Section 105(1) of the Companies Act, 2013, it is one of the restriction of Proxies.'),
(91, 'A proxy is not counted for the purpose of quorum of the general meeting of a company. True or False.', '["True","False","Partly True","Partly False, with permission of Chairman"]'::jsonb, 0, 'Section 105(1) of the Companies Act, 2013, it is one of the restriction of Proxies.'),
(92, 'Proxy have right to vote on poll in general meeting of the company. True or False.', '["True","False","Partly True, with permission of Chairman","Partly False, have right to vote but not in GM"]'::jsonb, 0, 'Section 105(1) of the Companies Act, 2013, it is one of the restriction of Proxies'),
(93, 'Proxy have right to demand a poll (if eligible u/s 109) in general meeting of the company. True or False.', '["True","False","Partly True, with permission of Chairman","Partly False, have right to demand but not in GM"]'::jsonb, 0, 'Section 105(1) of the Companies Act,'),
(94, 'The proxy shall file with the company in Form NoÃ¢â‚¬Â¦Ã¢â‚¬Â¦', '["MGT 8","MGT 9","MGT 10","MGT 11"]'::jsonb, 0, 'Section 105(1) of the'),
(95, 'The chairman of the meeting of a company received a Proxy 48 hours before the time fixed for the start of the meeting. He refused to accept the proxy on the ground that the Article of the company provided that a Proxy must be filed 60 hours before the start of the meeting. Whether Proxy holder can compel the chairman to admit the proxy?', '["Yes","No","Partly Yes(with the permission of BOD and shareholders)","Partly No"]'::jsonb, 3, 'Section'),
(96, 'The AOA of a Public company requires the instrument appointing a proxy to be received by the company 75 hours before the meeting. Is it valid requirement?', '["Yes","No","Partly Yes(with the permission of BOD and shareholders)","Partly No"]'::jsonb, 0, 'Section 105(7) of the Companies Act, 2013, if AOA of a'),
(97, 'State the grounds to bar a member from voting.', '["Any call or other sums presently payable by him have not been paid","The company has exercised any right of lien","Both a and b","either a or b"]'::jsonb, 1, 'Section 105(7) of the Companies Act, 2013, if AOA of a company requires for a longer period than 48 hours before meeting, such requirement by AOA shall be treated as 48 hours to deposit proxy form.'),
(100, 'Any company may use postal ballot for transacting any items of business other than', '["Ordinary Business","Any business in respect of which directors have a right to be heard","Any business in respect of which auditors have a right to be heard","All of the above"]'::jsonb, 1, 'Section 106 and 114(2) of the Companies Act, 2013, a resolution shall be a special resolution when the votes cast in favour of the resolution by members are not less than 3 times the number of votes, if any, cast against the resolution.'),
(101, 'State the types of Voting.', '["Voting by show of hands (Section 107 of the Companies Act, 2013)","Voting through Electronic Means (Section 108 of the Companies Act, 2013) and Postal ballot(Section 110 of the Companies Act, 2013)","Voting by Poll(Section 109 of the Companies Act, 2013)","All of the above"]'::jsonb, 3, 'Section 110(1) of the Companies Act, 2013, above items of business can be transacted only at a meeting.'),
(102, 'Entries have to be made in the Register within Ã¢â‚¬Â¦Ã¢â‚¬Â¦.days of the date of approval by the Board or Committee thereof by approving the allotment or transfer as the case may be.', '["7","15","30","60"]'::jsonb, 3, NULL),
(103, 'Joint holders of shares may request the company to', '["enter their names on the register in a certain order","execute transfers to have their holding split","Only one of their names should appear in the records of the company.","Both a and b"]'::jsonb, 0, 'Rule 5 of the Companies (Management & Administration) Rules, 2014.'),
(104, 'Maintenance of index of names in the registers is not necessary where the number of members is less thanÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["20","50","100","500"]'::jsonb, 3, 'The articles of most companies provide that, in the case of exclusion of the other joint holders, and for this purpose, seniority shall be determined by the order in which the names stand in the register of members.'),
(105, 'Where any declaration is received by the company regarding beneficial interest, the company shall make note of such declaration in the register of members and shall file, within a period of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..days from the date of receipt of declaration by it,', '["30","60","90","None of the above"]'::jsonb, 1, 'Rule 6 of the Companies (Management & Administration) Rules, 2014 states that the maintenance of index is not necessary where the number of members is less than 50.'),
(106, 'The register of members along with the index shall be preserved for', '["7 years","8 years","10 years","Permanently"]'::jsonb, 0, 'Where any declaration is received by the company under section 89, the company shall make note of such declaration in the register of members and shall file, within a period of 30 days from the date of receipt of declaration by it, a return in Form MGT - 6 with the ROC in respect of such declaration with the required fee.'),
(107, 'The company shall, within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.days from the date of the opening of any foreign register, file with the Registrar of Companies notice of the situation of the office.', '["7","30","60","90"]'::jsonb, 3, 'Section 94 of the Companies Act, 2013.'),
(108, 'A company opens the registers and indices from 1-2 p.m. every working day. Is it in contravention of Section 94?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 88 of the Companies Act, 2013. Ã¢â‚¬â€œ Foreign registers compliance.'),
(109, 'A holder of shares in a company who does not hold the beneficial interest such share, shall file with the company, a declaration to that effect in Form MGT Ã¢â‚¬â€4, in duplicate, within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.days from the date on which his name is entered in the register of', '["30","60","90","none of the above"]'::jsonb, 0, NULL),
(110, 'A beneficial owner, shall file with the company, a declaration disclosing such Interest In Form MGT-5 in duplicate, within Ã¢â‚¬Â¦Ã¢â‚¬Â¦..days after acquiring such beneficial Interest in the shares of the company.', '["30","60","90","none of the above"]'::jsonb, 0, 'A person whose name is entered in the register of members of a company as the holder of shares in that company but who does not hold the beneficial interest such share, shall file with the company, a declaration to that effect in Form MGT - 4, in duplicate, within 30 days from the date on which his name is entered in the register of members of such company.'),
(111, 'The company shall transmit to its registered office in India, a copy of every entry in any foreign register within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦days after the entry is made.', '["7","15","30","90"]'::jsonb, 0, 'Every person holding and exempted from furnishing declaration or acquiring a beneficial interest in shares of a company not registered in his name, shall file with the company, a declaration disclosing such interest in Form MGT 5 in duplication disclosing such interest in Form MGT 5 in duplicate, within 30 days after acquiring such beneficial interest in the shares of the company.'),
(112, 'The company which fails to comply with the provisions of section 89, makes punishable the company and every defaulting officer with a fine which shall not be less than RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. but which may go up to Rs. Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦with further fine of Rs. Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.per day during.', '["500, 1000,1000","1000, 3000, 1000","500, 3000, 1000","1000, 5000, 1000"]'::jsonb, 1, 'Section 88- Foreign Registers Compliances'),
(113, 'Copies of annual return along with the copy of certificates and the documents required to be annexed thereto shall be preserved for a period of years from the date of filing of the annual return.', '["7","8","10","20"]'::jsonb, 0, 'Section 89(7) refers to the company which falls to comply with the provisions of section 89, makes punishable the company and every defaulting officer with a fine which shall not be less than Rs. 500 but which may go up to Rs. 1,000 with'),
(114, 'The company and every officer of the company who fails to maintain registers as prescribed In the act shall be punishable with fine which shall not be less than Rs. Ã¢â‚¬Â¦Ã¢â‚¬Â¦.but which may extend to Rs. Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. And where the failure is a continuing one.', '["100000, 500000","50000, 300000","50000, 500000","100000, 300000"]'::jsonb, 1, NULL),
(115, 'If the beneficial owner or the holder of such shares fails to make a declaration on that behalf, they shall be fined with amount up to RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ and additionally RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ per day during which the failure continues. A., B.,', '["100000, 1000","50000, 3000","100000, 3000","50000, 1000"]'::jsonb, 1, 'Section 88 deals with the penalty for contravention of the provisions of section 88, i.e. failure to maintain registers in accordance with the provisions of Section 88(1) and 88(2) of the Act. It states that the company and every officer of the company who Is in default shall be punishable with fine which shall not be less'),
(116, 'Registers can be kept at any place in India In which more than Ã¢â‚¬Â¦Ã¢â‚¬Â¦of total members reside provided a special resolution has been passed at a general meeting.', '["1%","5%","10%","20%"]'::jsonb, 3, 'Section 89(5) applies to those who are required to make a declaration. But fail to do so. The penalty for their failure, without any reasonable explanation, is fine'),
(117, 'The annual return, filed by a listed company or a company having paid-up share capital of RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦.or more; or a turnover of RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦.. Crore or more, shall be certified by a Company Secretary in practice.', '["10, 50","20,100","50, 200","100, 500"]'::jsonb, 2, 'the registers shall be maintained at the registered office of the company unless a special resolution Is passed in a general meeting authorizing the keeping of the register at any other place within the city, town or village in which the registered office is situated or any other place in India in which more than 1/10th of the total members entered in the register of members reside.'),
(118, 'The extracts or copies of registers and indices can be taken by', '["any member","debenture holder","beneficial owner","All of the above"]'::jsonb, 0, 'The annual return, filed by a listed company or a company having paid- up share capital of Rs.10 crore or more; or a turnover of Rs.50 crore or more, shall be certified by a Company Secretary in practice'),
(119, 'The annual return has to be signed byÃ¢â‚¬Â¦..', '["CA, CS","CA, a director","CS, a Director","CA, CS and a director"]'::jsonb, 3, 'Any member, debenture holder or security holder or beneficial owner can take the extracts during any business without payment of any fee or can also get copies thereof with payment of fee not exceeding Rs.10 for each page. Such copies or entries or return shall be supplied within 7 days of deposit of fee.'),
(120, 'The company has to maintain registers of', '["members","debenture-holders","any other security holders","all of the above"]'::jsonb, 2, 'The annual return has to be signed by a director company and the company secretary; and in no company secretary, by a company secretary and in case, there is no company secretary, by a company secretary in practice.'),
(121, 'The annual return shall be file with the ROC within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ days from which the Annual General Meeting (Ã¢â‚¬ËœAGM'') is held or should have been held in any year,', '["15","30","60","90"]'::jsonb, 3, 'Section 88(1) of the Companies Act, 2013 seeks to provide that every company shall keep and maintain the register of members, register of debenture-holders and register of any other security holders.'),
(122, 'A company secretary in practice who signs the annual return can certify the same.', '["True","False","Partly True","Partly False"]'::jsonb, 2, 'The annual return shall be file with the ROC within 60 days from which the Annual General Meeting (''AGM) is held or should have been held in any year'),
(123, 'A company may close the register of members, debenture-holders and other security holders by giving minimum Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..notice or such lesser period as specified by SEBI.', '["21 clear days","30 days","7 days","15 days"]'::jsonb, 1, NULL),
(124, 'Inspection of registers and indices shall cost a maximum of RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦. or any lesser amount mentioned in the articles, for each inspection.', '["10","20","50","100"]'::jsonb, 2, 'A company may close the register of members, debenture- holders and other security holders by giving minimum 7 days'' notice or such lesser period as specified by Securities Exchange Board of India.'),
(125, 'In case of a company not limited by shares, the register shall not contain', '["Permanent Account Number or Corporate Identity Number","Nationality","Marital status","Date of becoming the member"]'::jsonb, 2, 'The registers and indices shall be open for inspection during business hours, at such reasonable time on event working day as the board may decide upon payment of fees as may be specified In the articles of association of the company, but which may not exceed RS. 50 for each Inspection. Also, a reasonable time shall be not less than 2 hours on every working day for which the inspection shall be open by the company.'),
(126, 'If a company secretary in practice, certifies the annual return otherwise than in accordance with this section and the rules made thereunder, he shall be punishable with fine which shall not be less than Rs.50, 000 but which may extend to RS. 5, 00,000 or Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["3 Months","6 Months","1 Year","2 Years"]'::jsonb, 2, 'In case of a company not limited by shares, the register shall contain the following particulars, in respect of each member- Name of the member, address (registered of address in case the member is a body corporate); email address; Permanent Account Number or Corporate Identity Number (''CIN); Nationality; in case member is a minor - name of his guardian and the date of birth of the member, name and address of the nominee; Date of becoming the member; Date of cessation; Amount of guarantee, if any; Any other interest, if any; and Instructions, if any, given by the member with regard to sending of notices, etc.'),
(127, 'The registers may be closed for any period not exceeding Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.days at any one time and for an aggregate period of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.days in one year.', '["30, 60","30, 45","45, 90","60, 90"]'::jsonb, 1, NULL),
(128, 'Every listed company is mandated to file with the ROC a return with respect to any changes In the number of shares held by Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.within 15 days of such change.', '["Directors and Promoters","Promoters and Top 10 shareholders","Directors and Top 10 shareholders","Directors, Promoters and Top 10 shareholders"]'::jsonb, 1, 'The registers may be closed for any period not exceeding 30 days at any one time and for an aggregate period of 45 days in one year.'),
(129, 'If the company defaults in filing the annual return, the company shall be punishable with fine which shall not be less than RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. but which may extend to RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["50000, 500000","100000, 500000","50000, 200000","100000, 200000"]'::jsonb, 1, NULL),
(130, 'Every listed company shall file in Form MGT -10 a return with respect to changes relating to either increase or decrease of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. percent or more in the shareholding position of promoters and top 10 shareholders of the company in each case.', '["1","2","5","10"]'::jsonb, 0, NULL),
(131, 'Section 90 simply enables the Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..to appoint one or more competent persons to investigate and report as to the beneficial ownership with regard to any share or class of shares.', '["Registrar","NCLT","Central Government","Company Law Board"]'::jsonb, 1, NULL),
(132, 'TheÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.has a casting vote in Board Meetings and general meetings, if specifically empowered by the articles of the Company.', '["Managing Director","Chartered Accountant","Company Secretary","Chairman"]'::jsonb, 2, NULL),
(136, 'The authorized representative of a corporate member can exercise the following rights :', '["right to speak","right to vote on poll","right to vote by show of hands","all of the above"]'::jsonb, 1, NULL),
(137, 'Special notice shall be sent by members to the company not earlier thanÃ¢â‚¬Â¦.. Months but at least Ã¢â‚¬Â¦Ã¢â‚¬Â¦days before the date of meeting.', '["1, 21 clear","3,21 clear","1, 14","3, 14"]'::jsonb, 3, 'A person authorized by resolution as above, shall be entitled to exercise the same rights and powers, including the right to vote by proxy and by postal ballot, on behalf of the body corporate which he represents as that body could exercise If It were an individual member, creditor or holder of debentures of the company.'),
(138, 'In a company with 1000 members the quorum is:', '["2","5","15","30"]'::jsonb, 3, NULL),
(139, 'For a private company quorum isÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Members personally present:', '["1","2","5","10"]'::jsonb, 3, NULL),
(140, 'Inspection of proxies can be done during the meeting and Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. Hours before the meeting before its commencement, and the inspection is to be given only during business hours.', '["12","24","48","72"]'::jsonb, 1, 'Section 103 of the Companies Act, 2013'),
(141, 'In order to properly call a general meeting the notice should be sent at least Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.days before the meeting, to all the members, legal representative of any deceased member or the assignee of insolvent members, the auditors and directors, in writing or electronic form.', '["21 days","21 clear days","21 full days","21 Complete days"]'::jsonb, 1, NULL),
(142, 'Any accidental omission to give notice to, or non-receipt of such notice to any member or other person who is entitled to such notice for any meeting shall invalidate the proceedings of the meeting.', '["True","False","Partly True","Partly False"]'::jsonb, 1, 'Section 101 of the Companies Act, 2013'),
(143, 'In case the meeting was called by the requisitionist under section 100 of the Act, then the same shall stand if the quorum is not present', '["adjourned","cancelled","members present will be quorum","No. of requisitionists will be quorum"]'::jsonb, 1, 'The omission must be designed or deliberate to invalidate the proceedings.'),
(144, 'The register of debenture-holder or any other security holder along with the index shall be preserved for a period of Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.years from the date preservative of register of debenture holding other security holder of redemption of debentures or securities.', '["7","8","10","20"]'::jsonb, 1, NULL),
(145, 'Notice of the general meeting shall be sent toÃ¢â‚¬Â¦Ã¢â‚¬Â¦', '["Assignee of the insolvent member","Managers of the corporate owners","Family member of deceased member","None of the above"]'::jsonb, 1, NULL),
(146, 'Section 104 of the Companies Act, 2013 seeks to provide that unless the articles of association of the Company otherwise provide, the members, personally present, shall elect among themselves to be the Chairman by:', '["Show of Hands","Poll","Postal Ballot","E-Voting"]'::jsonb, 0, NULL),
(149, 'If any inspection or the making of any extract or copy required under this section is refused, the company and every officer of the company who is in default, shall be liable for each such default, to a penalty of RSÃ¢â‚¬Â¦Ã¢â‚¬Â¦.. for every day subject to a maximum', '["1000, 100000","1000, 500000","2000, 200000","2000, 500000"]'::jsonb, 1, NULL),
(150, 'A proxy received Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..hours before the meeting will be valid even if the articles provide for a longer period.', '["12","24","48","72"]'::jsonb, 0, NULL),
(151, 'In case of the adjourned meeting or change of day, time or place of meeting Under section 103(2), the company shall give not less thanÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.. days'' notice to the members either individually or by publishing an advertisement in the newspaper.', '["2","3","4","5"]'::jsonb, 2, NULL),
(152, 'A person appointed as proxy shall act on behalf of such member or number of members not exceedingÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. and holding in aggregate not more than ......... per cent of the total share capital of the company carrying voting rights.', '["10, 5","10, 10","50, 10","20, 5"]'::jsonb, 1, NULL),
(154, 'A proxy shall have the following rights -', '["right to speak","right to vote on poll","right to vote by show of hands","all of the above"]'::jsonb, 2, 'The Ordinary Businesses as prescribed in the Section 102(2) of the Companies Act, 1956 are as follows: -the consideration of financial statements and the reports of the Board of Directors and auditors; -the declaration of any dividend; -the appointment of directors in place of those retiring; -the appointment of and the fixing of the remuneration of, the auditors; Any businesses except the above 4(four) businesses shall be deemed to be ''Special Businesses''.'),
(155, 'Who shall vote in case of joint holders if they are in disagreement?', '["any of the joint holders","determined on the basis of the order in which their names appear in the register","all of them","any of them"]'::jsonb, 1, 'A proxy shall not have the right to speak at such meeting and shall not be entitled to vote except on a poll.'),
(156, 'In a company with 5000 members the quorum is :', '["2","5","15","30"]'::jsonb, 1, 'The voting in case of joint shareholders Is done in the order of seniority, which is determined on the basis of the order In which their names appear In the register of members/ shareholders. The joint- holders have a right to Instruct the company as to the order In which their names are to appear in the register.'),
(157, 'Special notice is required:', '["To appoint as auditor a person other than a retiring auditor","To remove a director under section 169(2) or to appoint a person to fill the vacancy caused by the dismissal of a director","To stand for directorship by a person other than retiring director","all of the above"]'::jsonb, 2, NULL),
(158, 'A general meeting can be called on a shorter notice if Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦per cent of the members entitled to vote in that meeting give their consent in writing or by electronic mode.', '["85","90","95","100"]'::jsonb, 3, NULL),
(161, 'The gap between two AGMs shall not be more thanÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. months', '["12","15","18","21"]'::jsonb, 1, 'Section 109 of the Companies Act, 2013'),
(162, 'If a person is found guilty of tampering with the minutes of the proceedings of the meeting, he shall be punishable with imprisonment for a term which may extend to Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. years and with fine which shall not be less than RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ but which may extend to RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦..', '["1, 100000, 500000","2, 25000. 100000","1. 50000,500000","2, 50000, 500000"]'::jsonb, 1, 'Section 96 of the Companies Act, 2013'),
(163, 'Any of the following matter shall not be included in the minutes of the meeting, which in the opinion of the Chairman of the meeting:', '["Is or could reasonably be regarded as defamatory of any person","Is Irrelevant or immaterial to the proceedings;","Is detrimental to the interests of the company.","All of the above"]'::jsonb, 1, NULL),
(164, 'A general meeting can be called by', '["Board of directors","Requisitionists","NCLT","All of the above"]'::jsonb, 3, NULL),
(165, 'The company and every officer of the company who is in default or in contravention of section 96-98, shall be punishable with fine which may extend to RsÃ¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦. and in the case of a continuing default, with a further fine which may extend to Rs Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦.', '["100000, 5000","500000,1000","100000, 1000","500000, 5000"]'::jsonb, 3, 'Directors- u/s 96 of the Companies Act, 2013 NCLT- u/s 97&98 of the Companies Act, 2013 Requisitionists- u/s 100 of the Companies Act, 2013'),
(166, 'The minutes book of the general meeting shall be preserved for:', '["7 years","8 years","10 years","Permanently"]'::jsonb, 0, 'Section 99 of the Compani es Act, 2013'),
(167, 'Inspection of minuteÃ¢â‚¬â„¢s book can be carried out byÃ¢â‚¬Â¦Ã¢â‚¬Â¦', '["a member","a director","a debenture holder","all of the above"]'::jsonb, 3, NULL),
(168, 'If the Board does not call a meeting within Ã¢â‚¬Â¦Ã¢â‚¬Â¦Ã¢â‚¬Â¦ days from the date of receipt of requisition, then the requisitionists may themselves call a meeting within a period of Ã¢â‚¬Â¦Ã¢â‚¬Â¦..months from the date of requisition.', '["21, 3","21, 1","7, 1","7, 3"]'::jsonb, 0, 'Section 199 of the Companies Act, 2013'),
