-- Chapter 8: Audit and Auditors
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 8, 'Audit and Auditors', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'State the disqualification of auditor as per ICAI.', '["a person has not attend the age of 21 years","a person of unsound mind","an undischarged insolvent and convicted by court for any offence of moral turpitude","All of the above"]'::jsonb, 3, 'As per ICAI.'),
(2, 'The following which of the persons shall be eligible to appoint as auditor as per Companies Act, 2013.', '["Company registered under Companies Act, 2013","Any foreign company","Corporations","Limited Liability Partnership"]'::jsonb, 3, 'Section 141(3) (a) of the Companies Act, 2013, a body corporate other than LLP are not eligible to appoint as an auditor.'),
(3, 'Mr. Ram is an employee of the M/s ABC Ltd. He desires to appoint as an auditor of the company. Whether he can eligible to appoint as an auditor of M/s ABC Ltd.?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 141(3) (b) of the Companies Act, 2013, an officer or employee of the company are not eligible to appoint as an auditor.'),
(4, 'Whether an officer or employee of the company are eligible to appoint as auditor?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 141(3) (b) of the Companies Act, 2013, an officer or employee of the company a re not eligible to appoint as an auditor.'),
(5, 'Mr. Shyam is an employee of the M/s ABC Ltd. and partner of SR Partnership Firm. Mr. Ram (chartered Accountant), is another partner of SR Partnership Firm. Whether Mr. Ram is eligible to appoint as an auditor in M/s ABC Ltd.?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 141(3) (c) of the Companies Act, 2013, a person who is a partner or who is in the employment, of an officer or employee of the company.'),
(6, 'Mr. Ram is a relative of Mr. Shyam (chartered Accountant), is holding shares of Rs. 1, 00,000 in M/s ABC Ltd. Whether Mr. Shyam is eligible to appoint as auditor in M/s ABC Ltd.?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'Section 141(3) (d) of the Companies Act, 2013, a person who, or his relative or partner is holding any security of or interest in the company or its subsidiary or of its holding or associate company or a subsidiary of such holding company shall not eligibl e for appointment as an auditor of a company. Provided that the relative may hold security or interest in the company of face value such sum as may be prescribed i.e. Rs. 1, 00,000.'),
(7, 'Mr. Ram is a partner of Mr. Shyam (chartered Accountant), in a partnership firm, is holding shares of Rs. 1, 00,000 in M/s ABC Ltd. Whether Mr. Shyam is eligible to appoint as auditor in M/s ABC Ltd.?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 141(3) (d) of the Companies Act, 2013, a person who, or his relative or partner is holding any security of or interest in the company or its subsidiary or of its holding or associate company or a subsidiary of such holding company shall not eligible for appointment as an auditor of a company. Provided that the relative may hold security or interest in the company of face value such sum as may be prescribed i.e. Rs. 1, 00,000.'),
(8, 'Mr. Ram is a relative of Mr. Shyam (chartered Accountant), is holding shares of Rs. 1, 00,000 in M/s ABC Ltd. which is a subsidiary of M/s XYZ Ltd. Whether Mr. Shyam is eligible to appoint as auditor in M/s XYZ Ltd.?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 141(3) (d) of the Companies Act, 2013, a person who, or his relative or partner is holding any security of or int erest in the company or its subsidiary or of its holding or associate company or a subsidiary of such holding company shall not eligible for appointment as an auditor of a company. Provided that the relative may hold security or interest in the company (no t in subsidiary, associate or sister company of holding company) of face value such sum as may be prescribed i.e. Rs. 1, 00,000.'),
(9, 'Mr. Kiran is a partner of Mr. Rajesh (chartered Accountant), in a partnership firm, is holding shares of Rs. 50,000 in M/s ABC Ltd. which is a subsidiary of M/s XYZ Ltd. Whether Mr. Rajesh is eligible to appoint as auditor in M/s XYZ Ltd.?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 141(3) (d) of the Companies Act, 2013, a person who, or his relative or partner is holding any security of or interest in the company or its subsidiary or of its holding or associate company or a subsidiary of such holding company shall not eligible for appointment as an auditor of a company. Provided that the relative may hold security or interest in the comp any of face value such sum as may be prescribed i.e. Rs. 1, 00,000.'),
(10, 'Mr. Mohan is a partner of Mr. Sanjay (chartered Accountant), in a partnership firm, is holding shares of Rs. 10,000 in M/s MNC Ltd. which is an associate of M/s GHT Ltd. Whether Mr. Sanjay is eligible to appoint as auditor in M/s GHT Ltd.?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 141(3) (d) of the Companies Act, 2013, a person who, or his relative or partner is holding any security of or interest in the company or its subsidiary or of its holding or associate company or a subsidiary of such holding company shall not eligible for appointment as an auditor of a company. Provided that the relative may hold security or interest in the company of face value such sum as may be prescribed i.e. Rs. 1, 00,000.'),
